    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[allow(
        clippy::too_many_lines,
        reason = "one bounded test proves wrong-owner, persistence failure, retry, and disconnect invariants"
    )]
    async fn rename_promotion_is_atomic_on_persistence_failure() {
        let base = temp_dir();
        std::fs::create_dir(&base).unwrap();
        std::fs::set_permissions(&base, std::fs::Permissions::from_mode(0o700)).unwrap();
        let state = test_state_with_backend_and_metadata(
            false,
            test_pty_backend(),
            Some(MetadataStore::from_base(&base)),
        );
        let owner_id = 141;
        let Response::LairCreated { lair, .. } = trusted_request(
            &state,
            owner_id,
            Request::CreateTransientLair {
                expected_topology_revision: TopologyRevision::default(),
                name: "promoted-by-name".into(),
                launch: test_launch(&["/bin/sh", "-c", "sleep 30"]),
                generated_name: false,
            },
        )
        .await
        .unwrap() else {
            panic!("transient create response was not returned");
        };
        let dojo_id = lair.dojos[0].id;
        let before = state.topology.read().await.clone();
        let unauthorized = trusted_request(
            &state,
            owner_id + 1,
            Request::RenameDojo {
                expected_topology_revision: before.revision(),
                dojo_id,
                name: "unowned".into(),
                promote_transient_lair: true,
            },
        )
        .await
        .unwrap_err();
        assert_eq!(unauthorized.code, ErrorCode::Unauthorized);
        assert_eq!(*state.topology.read().await, before);

        state
            .topology_save_failure_countdown
            .store(0, Ordering::SeqCst);
        let error = trusted_request(
            &state,
            owner_id,
            Request::RenameDojo {
                expected_topology_revision: before.revision(),
                dojo_id,
                name: "work".into(),
                promote_transient_lair: true,
            },
        )
        .await
        .unwrap_err();
        assert_eq!(error.code, ErrorCode::Internal);
        assert_eq!(*state.topology.read().await, before);
        assert!(
            state
                .transient_leases
                .lock()
                .unwrap()
                .for_lair(lair.id)
                .is_some()
        );

        state
            .topology_save_failure_countdown
            .store(u64::MAX, Ordering::SeqCst);
        let response = trusted_request(
            &state,
            owner_id,
            Request::RenameDojo {
                expected_topology_revision: before.revision(),
                dojo_id,
                name: "work".into(),
                promote_transient_lair: true,
            },
        )
        .await
        .unwrap();
        assert!(matches!(response, Response::TopologyCommitted { .. }));
        let promoted = state
            .topology
            .read()
            .await
            .find_lair(lair.id)
            .unwrap()
            .clone();
        assert_eq!(promoted.lifetime, LairLifetime::Persistent);
        assert_eq!(promoted.dojos[0].name, "work");
        assert!(
            state
                .transient_leases
                .lock()
                .unwrap()
                .for_lair(lair.id)
                .is_none()
        );
        cleanup_connection(&state, owner_id).await;
        assert!(state.topology.read().await.find_lair(lair.id).is_some());
        let runtimes = state.runtimes.lock().await.drain();
        state.exit_observers.close();
        for runtime in runtimes {
            let _ = runtime.shutdown().await;
        }
        time::timeout(EXIT_OBSERVER_TIMEOUT, state.exit_observers.wait())
            .await
            .expect("exit observers did not finish before metadata cleanup");
        drop(state);
        std::fs::remove_dir_all(base).unwrap();
    }

    fn plain_shell_launch() -> splinterm_protocol::LaunchParameters {
        splinterm_protocol::LaunchParameters {
            shell: Some("/bin/sh".into()),
            ..test_launch(&[])
        }
    }

    async fn reap_all(state: &Arc<DaemonState>) {
        let runtimes = state.runtimes.lock().await.drain();
        for runtime in runtimes {
            let _ = runtime.shutdown().await;
        }
        await_retiring_reaped(state, "retiring runtimes were not reaped").await;
    }

    /// Waits until every retiring runtime is reaped. A retiring shell
    /// normally exits on its hangup within milliseconds, but one hung up
    /// just after it started occasionally survives it, and an interactive
    /// shell ignores SIGTERM: only the SIGKILL after both graces reaps it,
    /// about a minute later. The bound covers that whole escalation plus a margin
    /// for a loaded host, so only a runtime the SIGKILL never reaps fails.
    async fn await_retiring_reaped(state: &Arc<DaemonState>, failure: &str) {
        let config = daemon_live_config(state, 0);
        let escalation = config.exit_drain_timeout + config.hangup_grace + config.terminate_grace;
        time::timeout(escalation + Duration::from_secs(15), async {
            while state.retiring.count() > 0 {
                time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect(failure);
    }

    async fn create_plain_transient_dojo(
        state: &Arc<DaemonState>,
        connection_id: u64,
    ) -> (DojoId, SplintId, u64) {
        let expected_topology_revision = state.topology.read().await.revision();
        let Response::LairCreated {
            lair, incarnation, ..
        } = trusted_request(
            state,
            connection_id,
            Request::CreateTransientLair {
                expected_topology_revision,
                name: format!("attach {connection_id}"),
                launch: plain_shell_launch(),
                generated_name: false,
            },
        )
        .await
        .unwrap()
        else {
            panic!("transient create response was not returned");
        };
        (lair.dojos[0].id, lair.dojos[0].default_focus, incarnation)
    }

    /// Handles an Attach without counting its attachment, as the connection
    /// loop sees it before registering the subscription.
    async fn handled_attach(
        state: &Arc<DaemonState>,
        splint_id: SplintId,
        incarnation: u64,
    ) -> PendingSubscription {
        handle_authorized_request(
            Request::Attach {
                splint_id,
                incarnation: Some(incarnation),
                scrollback_rows: 0,
            },
            state,
            &PeerIdentity::for_test(),
            90,
            true,
            false,
            &RequestAuthorizationContext::default(),
            &mut HandoffAdmission::unfenced(),
        )
        .await
        .unwrap()
        .subscription
        .expect("Attach returns a terminal subscription")
    }

    // An Attach and an unused close never both succeed: an attach counted
    // first keeps the Dojo, and an attach still in flight when the close
    // claims the Splint is refused instead of being told it attached.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn attaches_and_unused_closes_exclude_each_other() {
        let state = test_state_with_backend(true, test_pty_backend());

        let (attached_dojo, attached_splint, attached_incarnation) =
            create_plain_transient_dojo(&state, 91).await;
        let subscription = handled_attach(&state, attached_splint, attached_incarnation).await;
        let attachment = register_attachment(&state, &subscription)
            .unwrap()
            .expect("a terminal subscription counts an attachment");
        let response = trusted_request(
            &state,
            91,
            Request::CloseUnusedDojo {
                dojo_id: attached_dojo,
            },
        )
        .await
        .unwrap();
        assert!(
            matches!(
                response,
                Response::UnusedDojoClose {
                    outcome: UnusedDojoCloseOutcome::Used {
                        reason: DojoUse::Attached
                    },
                    ..
                }
            ),
            "{response:?}"
        );
        drop(attachment);

        let (closed_dojo, closed_splint, closed_incarnation) =
            create_plain_transient_dojo(&state, 92).await;
        let in_flight = handled_attach(&state, closed_splint, closed_incarnation).await;
        let response = trusted_request(
            &state,
            92,
            Request::CloseUnusedDojo {
                dojo_id: closed_dojo,
            },
        )
        .await
        .unwrap();
        assert!(
            matches!(
                response,
                Response::UnusedDojoClose {
                    outcome: UnusedDojoCloseOutcome::Closed { .. },
                    ..
                }
            ),
            "{response:?}"
        );
        let refused = register_attachment(&state, &in_flight)
            .err()
            .expect("an attach that lost the race is refused");
        assert_eq!(refused.code, ErrorCode::NotFound);
        assert!(!state.attachments.is_attached(closed_splint));
        drop(in_flight);
        reap_all(&state).await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_held_unused_claim_refuses_attaches_until_released() {
        let registry = AttachmentRegistry::default();
        let state = test_state_with_backend(false, test_pty_backend());
        let (_, splint_id, _) = create_plain_transient_dojo(&state, 93).await;
        let handle = state.runtimes.lock().await.handle(splint_id).unwrap();
        let claim = registry.claim_unattached(handle.clone()).unwrap();
        assert!(registry.try_attach(&handle).is_none());
        drop(claim);
        let attachment = registry.try_attach(&handle).expect("released claim");
        assert!(matches!(
            registry.claim_unattached(handle.clone()),
            Err(DojoUse::Attached)
        ));
        drop(attachment);
        assert!(registry.claim_unattached(handle).is_ok());
        reap_all(&state).await;
    }

    // Only bytes the client flags as its own focus reports leave a runtime
    // unused; identical bytes from automation or a paste are input.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn only_flagged_focus_reports_leave_a_runtime_unused() {
        let state = test_state_with_backend(false, test_pty_backend());
        let Response::LairCreated { lair, .. } = trusted_request(
            &state,
            51,
            Request::CreateTransientLair {
                expected_topology_revision: TopologyRevision::default(),
                name: "focus".into(),
                launch: test_launch(&["/bin/sh", "-c", "sleep 30"]),
                generated_name: false,
            },
        )
        .await
        .unwrap() else {
            panic!("transient create response was not returned");
        };
        let handle = state
            .runtimes
            .lock()
            .await
            .handle(lair.dojos[0].default_focus)
            .unwrap();
        handle.focus_report(b"\x1b[I\x1b[O".to_vec()).await.unwrap();
        assert!(!handle.has_received_input(), "flagged focus reports");
        handle.focus_report(b"\x1b[Ix".to_vec()).await.unwrap();
        assert!(
            handle.has_received_input(),
            "a flag does not excuse other bytes"
        );

        let expected_topology_revision = state.topology.read().await.revision();
        let Response::LairCreated { lair, .. } = trusted_request(
            &state,
            52,
            Request::CreateTransientLair {
                expected_topology_revision,
                name: "pasted".into(),
                launch: test_launch(&["/bin/sh", "-c", "sleep 30"]),
                generated_name: false,
            },
        )
        .await
        .unwrap() else {
            panic!("transient create response was not returned");
        };
        let handle = state
            .runtimes
            .lock()
            .await
            .handle(lair.dojos[0].default_focus)
            .unwrap();
        handle.input(b"\x1b[I\x1b[O".to_vec()).await.unwrap();
        assert!(
            handle.has_received_input(),
            "unflagged focus-shaped bytes are input"
        );
        reap_all(&state).await;
    }

    // Status is display data bound to one incarnation. A status report is not
    // input, so the Dojo stays unused; when an unused close or a two-phase
    // Lair termination retires the Splint, the same transaction drops its status even
    // though the process may still be shutting down in the background.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn retired_splints_never_keep_their_agent_status() {
        let state = test_state_with_backend(true, test_pty_backend());
        let peer = PeerIdentity::for_test();
        let mut statuses = Vec::new();
        for connection_id in [71, 72] {
            let expected_topology_revision = state.topology.read().await.revision();
            let Response::LairCreated {
                lair, incarnation, ..
            } = trusted_request(
                &state,
                connection_id,
                Request::CreateTransientLair {
                    expected_topology_revision,
                    name: format!("status {connection_id}"),
                    launch: plain_shell_launch(),
                    generated_name: false,
                },
            )
            .await
            .unwrap()
            else {
                panic!("transient create response was not returned");
            };
            let splint_id = lair.dojos[0].default_focus;
            agent_status::handle_authorized_report(
                &state,
                &peer,
                &RequestAuthorizationContext::default(),
                &Request::ReportAgentStatus {
                    splint_id,
                    incarnation,
                    status: Some(splinterm_protocol::AgentStatusReport {
                        state: splinterm_protocol::AgentState::Working,
                        detail: None,
                        ttl_seconds: None,
                    }),
                },
            )
            .await
            .unwrap();
            statuses.push(splinterm_protocol::MutationTarget {
                lair_id: lair.id,
                dojo_id: lair.dojos[0].id,
                splint_id,
                incarnation,
            });
        }
        assert_eq!(state.agent_status.slot_count(), 2);

        let response = trusted_request(
            &state,
            71,
            Request::CloseUnusedDojo {
                dojo_id: statuses[0].dojo_id,
            },
        )
        .await
        .unwrap();
        assert!(
            matches!(
                response,
                Response::UnusedDojoClose {
                    outcome: UnusedDojoCloseOutcome::Closed { .. },
                    ..
                }
            ),
            "a status report is not use: {response:?}"
        );
        assert_eq!(state.agent_status.slot_count(), 1);

        let expected_topology_revision = state.topology.read().await.revision();
        trusted_request(
            &state,
            72,
            Request::TerminateLair {
                expected_topology_revision,
                lair_id: statuses[1].lair_id,
                targets: vec![statuses[1].clone()],
            },
        )
        .await
        .unwrap();
        assert_eq!(state.agent_status.slot_count(), 0);
        reap_all(&state).await;
    }

    // A request cancelled between claiming and closing (its client went away,
    // or the Window's deadline passed) must not leave the Splint refusing input.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_dropped_unused_close_claim_lets_input_through_again() {
        let state = test_state_with_backend(false, test_pty_backend());
        let Response::LairCreated { lair, .. } = trusted_request(
            &state,
            51,
            Request::CreateTransientLair {
                expected_topology_revision: TopologyRevision::default(),
                name: "claim".into(),
                launch: test_launch(&["/bin/sh", "-c", "sleep 30"]),
                generated_name: false,
            },
        )
        .await
        .unwrap() else {
            panic!("transient create response was not returned");
        };
        let handle = state
            .runtimes
            .lock()
            .await
            .handle(lair.dojos[0].default_focus)
            .unwrap();
        let claim = UnusedClaim::take(handle.clone()).expect("an unused runtime is claimed");
        assert!(UnusedClaim::take(handle.clone()).is_none(), "one claim");
        let refused = handle.input(b"x".to_vec()).await;
        assert!(matches!(refused, Err(LiveError::Retiring)), "{refused:?}");
        drop(claim);
        handle.input(b"x".to_vec()).await.unwrap();
        assert!(UnusedClaim::take(handle).is_none(), "input made it used");
        reap_all(&state).await;
    }

    // A transient Lair whose name Splinterm generated goes with its last
    // unused Dojo, and so does its Window-owned lease. A Lair the user named
    // stays, even under a name shaped like a generated one: the client's
    // provenance decides, not the name.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn an_unused_close_removes_an_empty_unnamed_transient_lair_and_its_lease() {
        let state = test_state_with_backend(false, test_pty_backend());
        let lookalike = splinterm_core::generated_lair_name(1_787_899_189_000, 8);
        for (connection_id, name, generated_name) in [
            (
                61,
                splinterm_core::generated_lair_name(1_787_899_189_000, 7),
                true,
            ),
            (62, "named".to_owned(), false),
            (63, lookalike, false),
        ] {
            let removed = generated_name;
            let expected_topology_revision = state.topology.read().await.revision();
            let Response::LairCreated { lair, .. } = trusted_request(
                &state,
                connection_id,
                Request::CreateTransientLair {
                    expected_topology_revision,
                    name,
                    launch: plain_shell_launch(),
                    generated_name,
                },
            )
            .await
            .unwrap() else {
                panic!("transient create response was not returned");
            };
            let response = trusted_request(
                &state,
                connection_id,
                Request::CloseUnusedDojo {
                    dojo_id: lair.dojos[0].id,
                },
            )
            .await
            .unwrap();
            let Response::UnusedDojoClose {
                outcome: UnusedDojoCloseOutcome::Closed { lair_removed, .. },
                ..
            } = response
            else {
                panic!("an unused Dojo was kept: {response:?}");
            };
            assert_eq!(lair_removed, removed);
            assert_eq!(
                state.topology.read().await.find_lair(lair.id).is_none(),
                removed
            );
            assert_eq!(
                state
                    .transient_leases
                    .lock()
                    .unwrap()
                    .for_connection(connection_id)
                    .is_none(),
                removed
            );
            assert!(!state.generated_lairs.lock().unwrap().contains(&lair.id));
        }
        reap_all(&state).await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn transient_owner_disconnect_reaps_runtime_and_removes_complete_lair() {
        let state = test_state_with_backend(false, test_pty_backend());
        let connection_id = 41;
        let response = trusted_request(
            &state,
            connection_id,
            Request::CreateTransientLair {
                expected_topology_revision: TopologyRevision::default(),
                name: "transient".into(),
                launch: test_launch(&["/bin/sh", "-c", "sleep 30"]),
                generated_name: false,
            },
        )
        .await
        .unwrap();
        let Response::LairCreated { lair, .. } = response else {
            panic!("transient create response was not returned");
        };
        assert_eq!(lair.lifetime, LairLifetime::Transient);
        let splint_id = lair.dojos[0].default_focus;
        // Grants on the transient workspace, once and while open.
        let lair_id = lair.id;
        state.grants.lock().await.grant_lair(
            &PeerIdentity::for_test(),
            lair_id,
            vec![AccessScope::Observe],
        );
        let agent = PeerIdentity::for_test_executing(
            executable_identity::ExecutableIdentity {
                path: PathBuf::from("/home/u/target/debug/agent"),
                device: 1,
                inode: 2,
                owner_uid: 1000,
                mode: 0o100_755,
                size: 1,
                sha256: "a".repeat(64),
            },
            agent_access::DurableEvidence::for_test(None, &[], false),
        );
        state
            .agent_access
            .commit_session(
                &agent,
                lair_id,
                agent_access::AccessSet::Level(agent_access::AccessLevel::Look),
                None,
            )
            .unwrap();
        let child_pid = state
            .runtimes
            .lock()
            .await
            .handle(splint_id)
            .unwrap()
            .child_pid();
        cleanup_connection(&state, connection_id + 1).await;
        assert!(state.topology.read().await.find_splint(splint_id).is_some());
        assert!(Path::new(&format!("/proc/{child_pid}")).exists());
        cleanup_connection(&state, connection_id).await;
        assert!(state.topology.read().await.lairs().next().is_none());
        // The workspace ended: its grants of every duration ended with it.
        assert!(state.grants.lock().await.lair_status(lair_id).is_empty());
        assert_eq!(state.agent_access.session_count_for_test(), 0);
        assert!(state.runtimes.lock().await.handle(splint_id).is_none());
        assert!(
            state
                .transient_leases
                .lock()
                .unwrap()
                .for_connection(connection_id)
                .is_none()
        );
        // Retirement reaps in the background, outside the topology transaction.
        await_retiring_reaped(&state, "retired transient runtime was not reaped").await;
        assert!(!Path::new(&format!("/proc/{child_pid}")).exists());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[allow(
        clippy::too_many_lines,
        reason = "one bounded test proves secondary exit and initial retirement together"
    )]
    async fn initial_exit_retires_transient_but_secondary_exit_does_not() {
        let state = test_state_with_backend(false, test_pty_backend());
        let connection_id = 42;
        let Response::LairCreated { lair, .. } = time::timeout(
            Duration::from_secs(5),
            trusted_request(
                &state,
                connection_id,
                Request::CreateTransientLair {
                    expected_topology_revision: TopologyRevision::default(),
                    name: "transient-secondary".into(),
                    launch: test_launch(&["/bin/sh", "-c", "sleep 30"]),
                    generated_name: false,
                },
            ),
        )
        .await
        .expect("transient create timed out")
        .unwrap() else {
            panic!("transient create response was not returned");
        };
        let initial_splint = lair.dojos[0].default_focus;
        let expected = state.topology.read().await.revision();
        let Response::DojoStarted { splint_id, .. } = time::timeout(
            Duration::from_secs(5),
            trusted_request(
                &state,
                99,
                Request::NewDojo {
                    expected_topology_revision: expected,
                    lair_id: lair.id,
                    name: "secondary".into(),
                    launch: test_launch(&["/bin/sh", "-c", "true"]),
                    promote_transient_lair: false,
                    generated_name: false,
                },
            ),
        )
        .await
        .expect("secondary Dojo create timed out")
        .unwrap() else {
            panic!("secondary Dojo response was not returned");
        };
        time::timeout(Duration::from_secs(5), async {
            loop {
                let exited = state
                    .topology
                    .read()
                    .await
                    .find_splint(splint_id)
                    .is_some_and(|splint| matches!(splint.state, SplintState::Exited(_)));
                if exited {
                    break;
                }
                time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        assert!(
            state
                .topology
                .read()
                .await
                .find_splint(initial_splint)
                .is_some()
        );
        time::timeout(
            Duration::from_secs(5),
            cleanup_connection(&state, connection_id),
        )
        .await
        .expect("owner cleanup timed out");
        assert!(state.topology.read().await.lairs().next().is_none());

        let state = test_state_with_backend(false, test_pty_backend());
        let Response::LairCreated { lair, .. } = time::timeout(
            Duration::from_secs(5),
            trusted_request(
                &state,
                43,
                Request::CreateTransientLair {
                    expected_topology_revision: TopologyRevision::default(),
                    name: "transient-exit".into(),
                    launch: test_launch(&["/bin/sh", "-c", "true"]),
                    generated_name: false,
                },
            ),
        )
        .await
        .expect("short transient create timed out")
        .unwrap() else {
            panic!("transient create response was not returned");
        };
        time::timeout(Duration::from_secs(5), async {
            loop {
                if state
                    .topology
                    .read()
                    .await
                    .lairs()
                    .all(|current| current.id != lair.id)
                {
                    break;
                }
                time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
    }

    #[test]
    fn human_roles_bypass_policy_only_for_their_supported_ui_surface() {
        assert!(policy_reload_disconnects(ClientRole::Automation));
        assert!(!policy_reload_disconnects(ClientRole::TrustedUi));
        assert!(!policy_reload_disconnects(ClientRole::RemoteInteractive));
        assert!(connection_revocation_disconnects(ClientRole::Automation));
        assert!(!connection_revocation_disconnects(ClientRole::TrustedUi));
        assert!(!connection_revocation_disconnects(
            ClientRole::RemoteInteractive
        ));
        assert!(!interactive_bypass(false, true, false, &Request::ListLairs));
        assert!(interactive_bypass(true, true, false, &Request::ListLairs));
        assert!(!interactive_bypass(true, false, false, &Request::ListLairs));
        assert!(!interactive_bypass(
            true,
            true,
            false,
            &Request::AuditInspect {
                after_audit_id: None,
                max_records: 1,
            }
        ));
        assert!(interactive_bypass(
            true,
            true,
            false,
            &Request::PublishGraphicalFocus {
                focused_splint_id: None,
            }
        ));
        assert!(interactive_bypass(false, false, true, &Request::ListLairs));
        let retention = Request::SetLairRetention {
            expected_topology_revision: TopologyRevision::new(7),
            lair_id: LairId::new(),
            retention: LairRetention::Saved,
        };
        assert!(interactive_bypass(true, true, false, &retention));
        assert!(interactive_bypass(false, false, true, &retention));
        assert!(!interactive_bypass(false, true, false, &retention));
        // Windows resolve launch directories without a policy rule; other
        // clients need the creation scopes.
        let resolve = Request::ResolveLaunchDirectory {
            source_splint_id: SplintId::new(),
            directory: splinterm_protocol::LaunchDirectory::Home,
        };
        assert!(interactive_bypass(true, true, false, &resolve));
        assert!(interactive_bypass(false, false, true, &resolve));
        assert!(!interactive_bypass(true, false, false, &resolve));
        assert!(!interactive_bypass(false, true, false, &resolve));
        let terminate_lair = Request::TerminateLair {
            expected_topology_revision: TopologyRevision::new(7),
            lair_id: LairId::new(),
            targets: Vec::new(),
        };
        assert!(interactive_bypass(true, true, false, &terminate_lair));
        assert!(interactive_bypass(false, false, true, &terminate_lair));
        assert!(!interactive_bypass(true, false, false, &terminate_lair));
        assert!(!interactive_bypass(false, true, false, &terminate_lair));
        // Local and remote Windows both close their unused Dojos.
        let close_unused = Request::CloseUnusedDojo {
            dojo_id: DojoId::new(),
        };
        assert!(interactive_bypass(true, true, false, &close_unused));
        assert!(interactive_bypass(false, false, true, &close_unused));
        assert!(!interactive_bypass(true, false, false, &close_unused));
        assert!(!interactive_bypass(false, true, false, &close_unused));
        assert!(!interactive_bypass(
            false,
            false,
            true,
            &Request::PublishGraphicalFocus {
                focused_splint_id: None,
            }
        ));
        let preset = Request::MaterializePreset {
            expected_topology_revision: TopologyRevision::default(),
            target: PresetTarget::NewLair {
                name: "preset".into(),
            },
            dojos: Vec::new(),
            directory_identities: Vec::new(),
        };
        assert!(interactive_bypass(true, true, false, &preset));
        assert!(!interactive_bypass(false, false, true, &preset));
        assert!(!intrinsically_authorized(
            &authorization::RequestAuthorization::TrustedUi,
            true,
        ));
        let peer = PeerIdentity::for_test();
        assert!(!first_party_human_ui(
            false,
            false,
            &peer,
            &[AccessScope::Input]
        ));
        assert!(first_party_human_ui(
            false,
            true,
            &peer,
            &[AccessScope::Input, AccessScope::Resize]
        ));
    }

    fn consent_responder_requests() -> [Request; 3] {
        [
            Request::SubscribeConsentOffers {
                kind: splinterm_protocol::ConsentResponderKind::Window,
            },
            Request::SubscribeConsentOffers {
                kind: splinterm_protocol::ConsentResponderKind::Terminal,
            },
            Request::AnswerConsentOffer {
                daemon_generation: 1,
                offer_id: 1,
                nonce: splinterm_protocol::ConsentOfferNonce::new(
                    [7; splinterm_protocol::CONSENT_OFFER_NONCE_BYTES],
                ),
                decision: ConsentDecision::Deny,
            },
        ]
    }

    /// ADR 0015: a Window responder is a remote Window's relay connection,
    /// the terminal approver is the installed local client, both may answer,
    /// and automation is never a responder.
    #[test]
    fn consent_responders_are_admitted_only_by_role_and_kind() {
        let [window, terminal, answer] = consent_responder_requests();
        // (request, installed trusted UI admitted, remote Window admitted)
        for (request, trusted_local, remote) in [
            (&window, false, true),
            (&terminal, true, false),
            (&answer, true, true),
        ] {
            assert!(trusted_ui_request(request), "{request:?}");
            // Neither development access nor policy admits them.
            assert!(!intrinsically_authorized(
                &authorization::for_request(request),
                true
            ));
            assert_eq!(requested_operation_scopes(request), Some(Vec::new()));
            for trusted_ui in [false, true] {
                for matching_splinterm in [false, true] {
                    for remote_interactive in [false, true] {
                        let expected = (trusted_ui && matching_splinterm && trusted_local)
                            || (remote_interactive && remote);
                        assert_eq!(
                            interactive_bypass(
                                trusted_ui,
                                matching_splinterm,
                                remote_interactive,
                                request
                            ),
                            expected,
                            "{request:?} trusted_ui={trusted_ui} \
                             matching={matching_splinterm} remote={remote_interactive}"
                        );
                        // The handler's own check agrees with the bypass for
                        // every real role (a connection has exactly one).
                        if !(trusted_ui && remote_interactive) {
                            assert_eq!(
                                consent_responder_admitted(
                                    trusted_ui,
                                    matching_splinterm,
                                    remote_interactive,
                                    request
                                ),
                                expected,
                                "{request:?} trusted_ui={trusted_ui} \
                                 matching={matching_splinterm} remote={remote_interactive}"
                            );
                        }
                    }
                }
            }
        }
        assert!(!consent_responder_admitted(
            true,
            true,
            true,
            &Request::Ping
        ));
    }

    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "every role, kind, and eligibility refusal of one request family"
    )]
    async fn consent_responder_requests_need_their_role_kind_and_an_eligible_process() {
        // Development terminal access never admits automation.
        let state = test_state(true);
        let mut peer = PeerIdentity::for_test();
        peer.install_persistent_executable(
            executable_identity::ExecutableIdentity::from_pid(std::process::id())
                .expect("snapshot test executable"),
        );
        let [window, terminal, answer] = consent_responder_requests();
        for request in [&window, &terminal, &answer] {
            // Automation, and a trusted UI role from a program that is not
            // the installed client.
            for (trusted_ui, remote_interactive) in [(false, false), (true, false)] {
                let error =
                    authorize_request(request, &state, &peer, 0, trusted_ui, remote_interactive)
                        .await
                        .unwrap_err();
                assert_eq!(error.code, ErrorCode::Unauthorized, "{request:?}");
                let error = handle_request(
                    request.clone(),
                    &state,
                    &peer,
                    1,
                    0,
                    trusted_ui,
                    remote_interactive,
                )
                .await
                .unwrap_err();
                assert_eq!(error.code, ErrorCode::Unauthorized, "{request:?}");
            }
            // The handler repeats the check for a trusted UI that is not the
            // installed client.
            assert_eq!(
                require_consent_responder(true, &peer, false, request)
                    .unwrap_err()
                    .code,
                ErrorCode::Unauthorized,
                "{request:?}"
            );
        }

        // A remote Window's role reaches the handler, whose `/proc` check
        // refuses this test process: it is not the installed relay.
        let error = handle_request(window.clone(), &state, &peer, 1, 0, false, true)
            .await
            .unwrap_err();
        assert_eq!(error.code, ErrorCode::Unauthorized);
        assert_eq!(state.consent_responders.responder_count(), 0);
        // An answer from a connection that is no responder finds nothing.
        let error = handle_request(answer.clone(), &state, &peer, 1, 0, false, true)
            .await
            .unwrap_err();
        assert_eq!(error.code, ErrorCode::NotFound);
        // The approver kind is the installed local client's only.
        let error = handle_request(terminal, &state, &peer, 1, 0, false, true)
            .await
            .unwrap_err();
        assert_eq!(error.code, ErrorCode::Unauthorized);
        // An out-of-bounds answer fails before any lookup.
        for (daemon_generation, offer_id) in [(0, 1), (1, 0)] {
            let request = Request::AnswerConsentOffer {
                daemon_generation,
                offer_id,
                nonce: splinterm_protocol::ConsentOfferNonce::new(
                    [7; splinterm_protocol::CONSENT_OFFER_NONCE_BYTES],
                ),
                decision: ConsentDecision::Deny,
            };
            let error = handle_request(request, &state, &peer, 1, 0, false, true)
                .await
                .unwrap_err();
            assert_eq!(error.code, ErrorCode::InvalidArgument);
        }
        // An eligible Window subscribes once per connection; its stream ends
        // the responder when dropped.
        state.consent_responders.set_probe(Arc::new(|_, _| Ok(())));
        let handled = handle_request(window.clone(), &state, &peer, 1, 0, false, true)
            .await
            .unwrap();
        let Response::ConsentOffersSubscribed { subscription_id } = handled.response else {
            panic!("a Window responder subscribes");
        };
        assert!(matches!(
            &handled.subscription,
            Some(PendingSubscription::ConsentOffers { stream })
                if stream.subscription_id() == subscription_id
        ));
        assert_eq!(
            handle_request(window.clone(), &state, &peer, 1, 0, false, true)
                .await
                .unwrap_err()
                .code,
            ErrorCode::ResourceLimit
        );
        drop(handled);
        assert_eq!(state.consent_responders.responder_count(), 0);
    }

    #[tokio::test]
    async fn daemon_handoff_requests_reach_only_the_installed_local_graphical_client() {
        let handoff_requests = [
            Request::PrepareDaemonHandoff {
                mode: splinterm_protocol::DaemonHandoffMode::DryRun,
            },
            Request::PrepareDaemonHandoff {
                mode: splinterm_protocol::DaemonHandoffMode::Execute,
            },
            Request::ClaimHandoffControl {
                ticket: splinterm_protocol::HandoffResumeTicket::new(
                    [7; splinterm_protocol::HANDOFF_RESUME_TICKET_BYTES],
                ),
                splint: None,
            },
            Request::AcknowledgeHandoffPrepare {
                daemon_generation: 1,
                prepare_id: 1,
            },
        ];
        // Development terminal access and remote human roles never stand in
        // for the trusted local graphical client.
        let state = test_state(true);
        let mut peer = PeerIdentity::for_test();
        peer.install_persistent_executable(
            executable_identity::ExecutableIdentity::from_pid(std::process::id())
                .expect("snapshot test executable"),
        );
        for request in &handoff_requests {
            assert!(trusted_ui_request(request));
            // Every combination of role and executable inputs: only a trusted
            // UI role from the installed graphical client bypasses policy.
            for trusted_ui in [false, true] {
                for matching_splinterm in [false, true] {
                    for remote_interactive in [false, true] {
                        assert_eq!(
                            interactive_bypass(
                                trusted_ui,
                                matching_splinterm,
                                remote_interactive,
                                request
                            ),
                            trusted_ui && matching_splinterm,
                            "{request:?} trusted_ui={trusted_ui} \
                             matching={matching_splinterm} remote={remote_interactive}"
                        );
                    }
                }
            }
            for (trusted_ui, remote_interactive) in [(false, false), (false, true), (true, false)] {
                let error =
                    authorize_request(request, &state, &peer, 0, trusted_ui, remote_interactive)
                        .await
                        .unwrap_err();
                assert_eq!(error.code, ErrorCode::Unauthorized, "{request:?}");
            }
        }
        // The handler repeats the role and executable check.
        assert_eq!(
            require_trusted_local_ui(true, &peer).unwrap_err().code,
            ErrorCode::Unauthorized
        );

        // Denials are audited like every other refused trusted operation,
        // and the ticket body is never recorded.
        for request in handoff_requests {
            let error = handle_request(request, &state, &peer, 1, 0, false, false)
                .await
                .unwrap_err();
            assert_eq!(error.code, ErrorCode::Unauthorized);
        }
        let audit = state.audit.lock().await.page(None, 16);
        let denied = audit
            .records
            .iter()
            .filter(|record| {
                matches!(
                    record.operation,
                    splinterm_protocol::AuditOperation::PrepareDaemonHandoff
                        | splinterm_protocol::AuditOperation::ClaimHandoffControl
                        | splinterm_protocol::AuditOperation::AcknowledgeHandoffPrepare
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(denied.len(), 4);
        for record in denied {
            assert_eq!(record.decision, splinterm_protocol::AuditDecision::Denied);
            assert_eq!(record.reason, "policy_rejected");
            assert_eq!(
                record.outcome,
                Some(splinterm_protocol::AuditOutcome::Failed)
            );
            assert!(record.resource.is_none());
            assert!(record.requested_scopes.is_empty());
        }
    }

    #[tokio::test]
    async fn invalid_handoff_ticket_is_audited_as_a_denial_without_the_ticket() {
        let state = test_state(false);
        let mut peer = PeerIdentity::for_test();
        peer.install_persistent_executable(
            executable_identity::ExecutableIdentity::from_pid(std::process::id())
                .expect("snapshot test executable"),
        );
        let request = Request::ClaimHandoffControl {
            ticket: splinterm_protocol::HandoffResumeTicket::new(
                [0xa7; splinterm_protocol::HANDOFF_RESUME_TICKET_BYTES],
            ),
            splint: None,
        };
        // The trusted UI passed authorization; the claim itself failed.
        let authorization = RequestAuthorizationContext {
            interactive_bypass: true,
            ..RequestAuthorizationContext::default()
        };
        append_request_result_audit(
            &state,
            &peer,
            &request,
            &authorization,
            None,
            &Err(handoff_requests::invalid_handoff_ticket()),
        )
        .await;
        let page = state.audit.lock().await.page(None, 16);
        let [record] = page.records.as_slice() else {
            panic!("exactly one audit record: {:?}", page.records);
        };
        assert_eq!(
            record.operation,
            splinterm_protocol::AuditOperation::ClaimHandoffControl
        );
        assert_eq!(record.decision, splinterm_protocol::AuditDecision::Denied);
        assert_eq!(record.reason, "authorization_denied");
        assert_eq!(
            record.outcome,
            Some(splinterm_protocol::AuditOutcome::Failed)
        );
        assert!(record.resource.is_none());
        assert!(record.policy_rule_id.is_none());
        let encoded = serde_json::to_string(record).unwrap();
        assert!(!encoded.contains("167,167"), "{encoded}");
        assert!(!encoded.contains("ticket"), "{encoded}");
    }

    /// Installs a hold of one relaunched Window, this test process, already
    /// issued `ticket` and holding the controllers of `controlled` (Plan 0061
    /// M3.16).
    fn ticketed_window_hold(
        state: &DaemonState,
        pinned: &consent::PinnedClientSnapshot,
        ticket: [u8; splinterm_protocol::HANDOFF_RESUME_TICKET_BYTES],
        controlled: &[&LiveSplintHandle],
    ) -> splinterd::handoff_window_carry::HandoffWindowHold {
        let pid = std::process::id();
        let hold = splinterd::handoff_window_carry::HandoffWindowHold::ticketed_for_test(
            pid,
            splinterd::handoff_window_carry::process_start_time(pid).unwrap(),
            rustix::process::pidfd_open(
                rustix::process::Pid::from_raw(i32::try_from(pid).unwrap()).unwrap(),
                rustix::process::PidfdFlags::empty(),
            )
            .unwrap(),
            pinned.identity(),
            state.daemon_generation,
            ticket,
            controlled
                .iter()
                .zip(41..)
                .map(|(handle, connection)| {
                    splinterd::handoff_window_carry::ControllerPlaceholder {
                        splint_id: handle.splint_id,
                        incarnation: handle.incarnation.value(),
                        window: 0,
                        connection,
                    }
                })
                .collect(),
            Instant::now() + Duration::from_secs(30),
        );
        *state.handoff_window_hold.lock().unwrap() = hold.clone();
        hold
    }

    fn handoff_claim(
        ticket: [u8; splinterm_protocol::HANDOFF_RESUME_TICKET_BYTES],
        splint_id: SplintId,
        incarnation: u64,
    ) -> Request {
        Request::ClaimHandoffControl {
            ticket: splinterm_protocol::HandoffResumeTicket::new(ticket),
            splint: Some(splinterm_protocol::HandoffClaimTarget {
                splint_id,
                incarnation,
            }),
        }
    }

    fn claimed_controllers(
        handled: Result<Handled, ProtocolError>,
    ) -> Vec<splinterm_protocol::HandoffClaimedController> {
        match handled.unwrap().response {
            Response::HandoffControlClaimed { controllers } => controllers,
            response => panic!("not a claim result: {response:?}"),
        }
    }

    fn pinned_window_peer(pinned: &Arc<consent::PinnedClientSnapshot>) -> PeerIdentity {
        let mut peer = PeerIdentity::for_test_pinned(Arc::clone(pinned));
        peer.install_persistent_executable(
            executable_identity::ExecutableIdentity::from_pid(std::process::id())
                .expect("snapshot test executable"),
        );
        assert!(peer.is_matching_splinterm());
        // Its connection said Hello as the pinned client.
        peer.record_hello_client_match(None, &consent::TrustedClientProcesses::default());
        assert!(peer.connection_matches_splinterm());
        peer
    }

    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "one claim walk: restored, replayed, live-held, stale, and ended"
    )]
    async fn a_resume_ticket_restores_exactly_the_named_live_unheld_controllers() {
        let state = test_state_with_backend(false, test_pty_backend());
        let handles = live_cat_splints(&state, 3).await;
        let [first, second, third] = [&handles[0], &handles[1], &handles[2]];
        let pinned = Arc::new(consent::PinnedClientSnapshot::own_executable_for_test());
        let peer = pinned_window_peer(&pinned);
        let ticket = [0x9b; splinterm_protocol::HANDOFF_RESUME_TICKET_BYTES];
        let hold = ticketed_window_hold(&state, &pinned, ticket, &[first, second, third]);
        // Another connection took the second Splint's controller after the
        // adoption.
        let live_owner = state
            .controller
            .lock()
            .await
            .acquire(77, second.splint_id, second.incarnation.value(), None)
            .unwrap()
            .id;

        // The first pane's new control connection restores its controller.
        let restored = claimed_controllers(
            handle_request(
                handoff_claim(ticket, first.splint_id, first.incarnation.value()),
                &state,
                &peer,
                501,
                0,
                true,
                false,
            )
            .await,
        );
        let [restored] = restored.as_slice() else {
            panic!("exactly one controller: {restored:?}");
        };
        assert_eq!(
            (restored.splint_id, restored.incarnation),
            (first.splint_id, first.incarnation.value())
        );
        assert_eq!(
            restored.modes,
            [
                splinterm_protocol::ControlMode::Input,
                splinterm_protocol::ControlMode::Resize
            ]
        );
        {
            let controllers = state.controller.lock().await;
            controllers
                .authorize(
                    501,
                    restored.controller_id,
                    first.splint_id,
                    first.incarnation.value(),
                )
                .unwrap();
            assert!(
                controllers
                    .by_id
                    .get(&restored.controller_id)
                    .is_some_and(|lease| lease.grant_id.is_none())
            );
        }
        // A replay, on any connection, restores nothing.
        assert_eq!(
            handle_request(
                handoff_claim(ticket, first.splint_id, first.incarnation.value()),
                &state,
                &peer,
                502,
                0,
                true,
                false,
            )
            .await
            .unwrap_err()
            .code,
            ErrorCode::InvalidHandoffTicket
        );
        // A Splint with a live controller now is skipped, never forced.
        assert!(
            claimed_controllers(
                handle_request(
                    handoff_claim(ticket, second.splint_id, second.incarnation.value()),
                    &state,
                    &peer,
                    503,
                    0,
                    true,
                    false,
                )
                .await
            )
            .is_empty()
        );
        state
            .controller
            .lock()
            .await
            .authorize(77, live_owner, second.splint_id, second.incarnation.value())
            .unwrap();
        // A claim naming another incarnation than the held one is skipped.
        assert!(
            claimed_controllers(
                handle_request(
                    handoff_claim(ticket, third.splint_id, third.incarnation.value() + 1),
                    &state,
                    &peer,
                    504,
                    0,
                    true,
                    false,
                )
                .await
            )
            .is_empty()
        );
        assert!(
            !state
                .controller
                .lock()
                .await
                .by_splint
                .contains_key(&third.splint_id)
        );
        // Every placeholder is spent: the ticket and the hold ended.
        assert!(!hold.is_held());
        assert_eq!(
            handle_request(
                handoff_claim(ticket, third.splint_id, third.incarnation.value()),
                &state,
                &peer,
                505,
                0,
                true,
                false,
            )
            .await
            .unwrap_err()
            .code,
            ErrorCode::InvalidHandoffTicket
        );
    }

    #[tokio::test]
    async fn a_handoff_claim_from_another_role_or_without_a_splint_never_spends_the_ticket() {
        let state = test_state_with_backend(false, test_pty_backend());
        let handles = live_cat_splints(&state, 1).await;
        let splint = &handles[0];
        let pinned = Arc::new(consent::PinnedClientSnapshot::own_executable_for_test());
        let peer = pinned_window_peer(&pinned);
        let ticket = [0x2d; splinterm_protocol::HANDOFF_RESUME_TICKET_BYTES];
        let claim = || handoff_claim(ticket, splint.splint_id, splint.incarnation.value());
        // Nothing is held yet: no ticket is valid.
        assert_eq!(
            handle_request(claim(), &state, &peer, 501, 0, true, false)
                .await
                .unwrap_err()
                .code,
            ErrorCode::InvalidHandoffTicket
        );
        let hold = ticketed_window_hold(&state, &pinned, ticket, &[splint]);
        // An automation or relay connection, or a trusted-UI role on any
        // client but the installed or pinned one, is refused before the
        // ticket is looked at.
        for (trusted_ui, remote_interactive) in [(false, false), (false, true)] {
            assert_eq!(
                handle_request(
                    claim(),
                    &state,
                    &peer,
                    502,
                    0,
                    trusted_ui,
                    remote_interactive
                )
                .await
                .unwrap_err()
                .code,
                ErrorCode::Unauthorized
            );
        }
        assert_eq!(
            handle_request(
                claim(),
                &state,
                &PeerIdentity::for_test(),
                503,
                0,
                true,
                false
            )
            .await
            .unwrap_err()
            .code,
            ErrorCode::Unauthorized
        );
        // A claim that names no Splint, or incarnation zero.
        for request in [
            Request::ClaimHandoffControl {
                ticket: splinterm_protocol::HandoffResumeTicket::new(ticket),
                splint: None,
            },
            handoff_claim(ticket, splint.splint_id, 0),
        ] {
            assert_eq!(
                handle_request(request, &state, &peer, 504, 0, true, false)
                    .await
                    .unwrap_err()
                    .code,
                ErrorCode::InvalidArgument
            );
        }
        assert_eq!(hold.placeholders().len(), 1);
        // The ticket still restores for its Window.
        assert_eq!(
            claimed_controllers(handle_request(claim(), &state, &peer, 505, 0, true, false).await)
                .len(),
            1
        );
    }

    /// Live handoff is supported for this build, so the dry run names only
    /// what really blocks it: the open transient Lair and the missing
    /// package installation. `Execute` is refused for those before the gate.
    #[tokio::test]
    async fn dry_run_reports_current_state_and_refused_execute_changes_nothing() {
        let state = test_state(false);
        let transient = Lair::transient("transient", PathBuf::from("/tmp"));
        let transient_id = transient.id;
        {
            let mut topology = state.topology.write().await;
            let revision = topology.revision();
            topology.insert_lair_at(revision, transient).unwrap();
        }
        let report = daemon_handoff_report(&state).await.unwrap();
        report.validate().unwrap();
        assert_eq!(report.daemon_generation, state.daemon_generation);
        assert_eq!(
            (report.lairs, report.transient_lairs, report.dojos),
            (1, 1, 1)
        );
        assert_eq!(report.live_splints, 0);
        assert!(!report.rollback_available);
        assert_eq!(
            report.blocking_reasons,
            [
                splinterm_protocol::HandoffBlockingReason::TransientLairsOpen {
                    count: 1,
                    lair_ids: vec![transient_id],
                },
                splinterm_protocol::HandoffBlockingReason::NotPackaged,
            ]
        );
        assert_eq!(
            handoff_requests::live_handoff_support(report.build.provenance),
            Ok(())
        );
        let revision = state.topology.read().await.revision();
        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let refused = execute_daemon_handoff(&state, &report, None).await;
        assert_eq!(refused.code, ErrorCode::HandoffUnavailable);
        assert_eq!(refused.message, "daemon handoff is unavailable");
        assert_eq!(refused.handoff_blocking_reasons, report.blocking_reasons);
        assert_eq!(
            state.topology.read().await.revision(),
            revision,
            "a refused handoff changes nothing"
        );
        // Refused before the gate: nothing was fenced or broadcast.
        assert!(handoff_status_phases(&mut subscription).is_empty());
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
    }

    /// The report of a daemon nothing blocks. With live handoff support
    /// passed as `Ok(())` (unit tests only), it lets the gate run.
    async fn gated_handoff_report(state: &DaemonState) -> splinterm_protocol::HandoffReport {
        let mut report = daemon_handoff_report(state).await.unwrap();
        report.blocking_reasons.clear();
        report
    }

    /// The shipped `Execute` evaluates live handoff support itself, from the
    /// report's provenance. Live handoff is enabled, but a Nix-store build is
    /// still unsupported for 0.2.0: even a report that names no reason is
    /// refused before the gate. The answer names `Unsupported` and Nix, and
    /// nothing is fenced, prepared, or broadcast.
    #[tokio::test]
    async fn execute_is_refused_before_the_gate_while_live_handoff_is_unsupported() {
        let state = test_state(false);
        let mut report = gated_handoff_report(&state).await;
        report.build.provenance = splinterm_protocol::HandoffBuildProvenance::NixStore;
        let support = handoff_requests::live_handoff_support(report.build.provenance);
        assert_eq!(
            support,
            Err(handoff_requests::LiveHandoffUnsupported::NixStore)
        );
        let revision = state.topology.read().await.revision();
        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let prepared = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let refused = execute_daemon_handoff_with(&state, &report, support, None, {
            let prepared = Arc::clone(&prepared);
            move |_| async move {
                prepared.store(true, Ordering::SeqCst);
                Ok(ExecTestPreparation)
            }
        })
        .await;
        assert_eq!(refused.code, ErrorCode::HandoffUnavailable);
        assert_eq!(
            refused.handoff_blocking_reasons,
            [splinterm_protocol::HandoffBlockingReason::Unsupported]
        );
        assert_eq!(
            refused.message,
            format!(
                "daemon handoff is unavailable: {}",
                handoff_requests::LiveHandoffUnsupported::NixStore.message()
            )
        );
        // The shipped wrapper gives the same answer.
        let shipped = execute_daemon_handoff(&state, &report, None).await;
        assert_eq!(shipped.message, refused.message);
        assert_eq!(
            shipped.handoff_blocking_reasons,
            refused.handoff_blocking_reasons
        );
        assert!(!prepared.load(Ordering::SeqCst));
        assert!(handoff_status_phases(&mut subscription).is_empty());
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
        assert!(!state.handoff_exit.is_ready());
        assert_eq!(state.topology.read().await.revision(), revision);
    }

    /// Live handoff is enabled: for this build's own provenance the shipped
    /// `Execute` no longer stops before the gate once nothing blocks it. It
    /// begins the attempt and prepares the installed forward pair, which a
    /// daemon without a package installation cannot, so the attempt cancels
    /// as failed and the fresh report names `NotPackaged` alone.
    #[tokio::test]
    async fn the_shipped_execute_reaches_the_gate_for_a_supported_build() {
        let state = test_state(false);
        let report = gated_handoff_report(&state).await;
        assert_eq!(
            handoff_requests::live_handoff_support(report.build.provenance),
            Ok(())
        );
        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let error = execute_daemon_handoff(&state, &report, None).await;
        assert_eq!(error.code, ErrorCode::HandoffUnavailable);
        assert_eq!(
            error.message,
            "daemon handoff is unavailable: preparation could not complete"
        );
        assert_eq!(
            error.handoff_blocking_reasons,
            [splinterm_protocol::HandoffBlockingReason::NotPackaged]
        );
        assert_eq!(
            handoff_status_phases(&mut subscription),
            [
                HandoffStatusPhase::Preparing,
                cancelled(HandoffCancelReason::Failed),
            ]
        );
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
        assert!(!state.handoff_exit.is_ready());
    }

    /// Plan 0061 D8: a daemon started by a live handoff (adopted forward or
    /// rollback) refuses another `Execute` before the gate until it restarts,
    /// even with live handoff support forced and a report naming no reason.
    /// Nothing is prepared, fenced, or broadcast, and the answer says that a
    /// restart comes first.
    #[tokio::test]
    async fn an_adopted_daemon_refuses_another_handoff_before_the_gate() {
        let mut state = test_state(false);
        Arc::get_mut(&mut state).unwrap().rollback_handoff =
            Arc::new(handoff_requests::RollbackAuthority::SpentByHandoff);
        let full = daemon_handoff_report(&state).await.unwrap();
        assert!(!full.rollback_available);
        let report = gated_handoff_report(&state).await;
        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let prepared = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let refused = execute_daemon_handoff_with(&state, &report, Ok(()), None, {
            let prepared = Arc::clone(&prepared);
            move |_| async move {
                prepared.store(true, Ordering::SeqCst);
                Ok(ExecTestPreparation)
            }
        })
        .await;
        assert_eq!(refused.code, ErrorCode::HandoffUnavailable);
        assert_eq!(
            refused.message,
            format!(
                "daemon handoff is unavailable: {}",
                handoff_requests::SPENT_BY_HANDOFF
            )
        );
        // The shipped wrapper, with the full report, names the restart too.
        let shipped = execute_daemon_handoff(&state, &full, None).await;
        assert!(
            shipped.message.contains(handoff_requests::SPENT_BY_HANDOFF),
            "{}",
            shipped.message
        );
        assert!(!prepared.load(Ordering::SeqCst));
        assert!(handoff_status_phases(&mut subscription).is_empty());
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
        assert!(!state.handoff_exit.is_ready());
    }

    /// Runs `Execute` as a packaged daemon with an installed upgrade would:
    /// forward preparation succeeds at once, so the gate goes on to fence.
    async fn execute_with_forward_prepared(
        state: &Arc<DaemonState>,
        report: &splinterm_protocol::HandoffReport,
    ) -> ProtocolError {
        execute_daemon_handoff_with(state, report, Ok(()), None, |_| async { Ok(()) }).await
    }

    /// Every handoff status phase queued for a topology hub subscriber.
    fn handoff_status_phases(subscription: &mut TopologySubscription) -> Vec<HandoffStatusPhase> {
        let mut phases = Vec::new();
        while let Ok(event) = subscription.changes.try_recv() {
            if let TopologyHubEvent::Status(event) = event
                && let SubscriptionEvent::HandoffStatus {
                    daemon_generation,
                    phase,
                } = *event
            {
                assert_eq!(daemon_generation, handoff_requests::FRESH_DAEMON_GENERATION);
                phases.push(phase);
            }
        }
        phases
    }

    /// Waits for a dropped attempt's spawned cancellation to return the gate.
    async fn wait_for_idle_gate(state: &DaemonState) {
        time::timeout(Duration::from_secs(5), async {
            while state.handoff_gate.phase() != HandoffGatePhase::Idle {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("a dropped handoff attempt returns the gate to idle");
    }

    fn cancelled(reason: HandoffCancelReason) -> HandoffStatusPhase {
        HandoffStatusPhase::Cancelled { reason }
    }

