    #[tokio::test]
    async fn a_second_execute_is_refused_while_a_handoff_runs_and_a_dry_run_still_reports() {
        let state = test_state(false);
        let report = gated_handoff_report(&state).await;
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Preparing);
        assert_eq!(
            execute_daemon_handoff(&state, &report, None).await.code,
            ErrorCode::HandoffInProgress
        );
        assert_eq!(
            HandoffAttempt::begin(&state).await.err().unwrap().code,
            ErrorCode::HandoffInProgress
        );
        attempt.fence().await.unwrap();
        assert_eq!(
            execute_daemon_handoff(&state, &report, None).await.code,
            ErrorCode::HandoffInProgress
        );
        // A dry run takes no topology permit, so it answers under the fence.
        let dry_run = time::timeout(Duration::from_secs(1), daemon_handoff_report(&state))
            .await
            .expect("a dry run never waits for the fence")
            .unwrap();
        // The point-in-time report under the fence: this development daemon
        // is not packaged, and live handoff itself is supported.
        assert_eq!(
            dry_run.blocking_reasons,
            [splinterm_protocol::HandoffBlockingReason::NotPackaged]
        );
        attempt.cancel(HandoffCancelReason::Requested).await;
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
    }

    #[tokio::test]
    async fn fenced_requests_are_refused_while_fenced_and_admitted_after_cancel() {
        let state = test_state(true);
        let mut peer = PeerIdentity::for_test();
        peer.install_persistent_executable(
            executable_identity::ExecutableIdentity::from_pid(std::process::id())
                .expect("snapshot test executable"),
        );
        let lair = Lair::new("durable", PathBuf::from("/tmp"));
        let lair_id = lair.id;
        {
            let mut topology = state.topology.write().await;
            let revision = topology.revision();
            topology.insert_lair_at(revision, lair).unwrap();
        }
        let rename = |name: &str, revision| Request::RenameLair {
            expected_topology_revision: revision,
            lair_id,
            name: name.into(),
        };
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        // Preparing still serves normally.
        let revision = state.topology.read().await.revision();
        handle_request(
            rename("preparing", revision),
            &state,
            &peer,
            1,
            0,
            false,
            false,
        )
        .await
        .unwrap();
        attempt.fence().await.unwrap();
        let revision = state.topology.read().await.revision();
        let refused = handle_request(
            rename("fenced", revision),
            &state,
            &peer,
            1,
            0,
            false,
            false,
        )
        .await
        .unwrap_err();
        assert_eq!(refused.code, ErrorCode::HandoffInProgress);
        assert_eq!(state.topology.read().await.revision(), revision);
        let input = Request::Input {
            controller_id: 1,
            splint_id: SplintId::new(),
            incarnation: 1,
            bytes: b"x".to_vec(),
            focus_report: false,
        };
        assert_eq!(
            handle_request(input, &state, &peer, 1, 0, false, false)
                .await
                .unwrap_err()
                .code,
            ErrorCode::HandoffInProgress
        );
        // Read-only queries are admitted under the fence.
        let listed = handle_request(Request::ListLairs, &state, &peer, 1, 0, false, false)
            .await
            .unwrap();
        assert!(matches!(listed.response, Response::Lairs { .. }));

        // The refusal is audited as an authorized request that failed.
        let page = state.audit.lock().await.page(None, 16);
        let refused_record = page
            .records
            .iter()
            .find(|record| {
                record.operation == splinterm_protocol::AuditOperation::RenameLair
                    && record.outcome == Some(splinterm_protocol::AuditOutcome::Failed)
            })
            .expect("the fenced rename is audited");
        assert_eq!(
            refused_record.decision,
            splinterm_protocol::AuditDecision::Allowed
        );
        assert_eq!(refused_record.reason, "trusted_or_owned_authority");

        attempt.cancel(HandoffCancelReason::Requested).await;
        handle_request(
            rename("admitted", revision),
            &state,
            &peer,
            1,
            0,
            false,
            false,
        )
        .await
        .unwrap();
        assert_eq!(
            state.topology.read().await.find_lair(lair_id).unwrap().name,
            "admitted"
        );
    }

    /// A fenced request whose handler is held mid-flight: `DecideControlTransfer`
    /// passes the choke point and then waits for the controller lock the test
    /// holds.
    fn held_fenced_request() -> Request {
        Request::DecideControlTransfer {
            transfer_id: 1,
            decision: ControlTransferDecision::Deny,
        }
    }

    fn spawn_request(
        state: &Arc<DaemonState>,
        request: Request,
    ) -> tokio::task::JoinHandle<Result<Response, ProtocolError>> {
        let state = Arc::clone(state);
        tokio::spawn(async move {
            handle_request(
                request,
                &state,
                &PeerIdentity::for_test(),
                1,
                0,
                false,
                false,
            )
            .await
            .map(|handled| handled.response)
        })
    }

    /// Waits until a fenced request holds its admission.
    async fn wait_for_admitted_request(state: &DaemonState) {
        time::timeout(Duration::from_secs(5), async {
            while state.handoff_in_flight.try_write().is_ok() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the fenced request is admitted");
    }

    #[tokio::test]
    async fn the_fence_waits_for_fenced_handlers_in_flight_and_refuses_later_ones() {
        let state = test_state(false);
        let ping = || async {
            time::timeout(
                Duration::from_secs(1),
                handle_request(
                    Request::Ping,
                    &state,
                    &PeerIdentity::for_test(),
                    1,
                    0,
                    false,
                    false,
                ),
            )
            .await
            .expect("an unfenced request never waits for the fence")
            .unwrap()
            .response
        };
        let controller = state.controller.lock().await;
        let in_flight = spawn_request(&state, held_fenced_request());
        wait_for_admitted_request(&state).await;

        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        let fence = tokio::spawn(async move {
            let fenced = attempt.fence().await;
            (attempt, fenced)
        });
        // The fence queues for the guard behind the handler, which holds new
        // admissions back.
        time::timeout(Duration::from_secs(5), async {
            while state.handoff_in_flight.try_read().is_ok() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the fence waits for the in-flight handler");
        let late = spawn_request(&state, held_fenced_request());
        time::sleep(Duration::from_millis(100)).await;
        assert_eq!(
            state.handoff_gate.phase(),
            HandoffGatePhase::Preparing,
            "no fence while a fenced handler runs"
        );
        assert!(!fence.is_finished());
        assert!(
            !late.is_finished(),
            "a new fenced request waits out the drain"
        );
        assert!(
            state.topology_transactions.try_acquire().is_ok(),
            "the fence takes the permit only after the drain"
        );
        assert!(matches!(ping().await, Response::Pong));

        // The handler finishes on its own terms, then the fence goes up.
        drop(controller);
        let finished = time::timeout(Duration::from_secs(5), in_flight)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            finished.unwrap_err().code,
            ErrorCode::HandoffInProgress,
            "an admitted handler runs to its own end"
        );
        let (attempt, fenced) = time::timeout(Duration::from_secs(5), fence)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(fenced, Ok(()));
        assert!(state.handoff_gate.is_fenced());
        // The request held back by the drain, and any later one, is refused.
        let late = time::timeout(Duration::from_secs(5), late)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(late.unwrap_err().code, ErrorCode::HandoffInProgress);
        assert_eq!(
            spawn_request(&state, held_fenced_request())
                .await
                .unwrap()
                .unwrap_err()
                .code,
            ErrorCode::HandoffInProgress
        );
        assert!(matches!(ping().await, Response::Pong));
        assert!(
            state.handoff_in_flight.try_write().is_ok(),
            "a refused request holds no admission"
        );

        attempt.cancel(HandoffCancelReason::Requested).await;
        assert_ne!(
            spawn_request(&state, held_fenced_request())
                .await
                .unwrap()
                .unwrap_err()
                .code,
            ErrorCode::HandoffInProgress
        );
    }

    #[tokio::test(start_paused = true)]
    async fn a_fenced_handler_that_never_finishes_times_the_fence_out() {
        let state = test_state(false);
        let controller = state.controller.lock().await;
        let in_flight = spawn_request(&state, held_fenced_request());
        wait_for_admitted_request(&state).await;
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(attempt.fence().await, Err(HandoffCancelReason::TimedOut));
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Preparing);
        assert!(
            state.topology_transactions.try_acquire().is_ok(),
            "a timed-out fence holds no permit"
        );
        attempt.cancel(HandoffCancelReason::TimedOut).await;
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
        // The handler was never cut short and still runs once it can.
        assert!(!in_flight.is_finished());
        drop(controller);
        assert_ne!(
            in_flight.await.unwrap().unwrap_err().code,
            ErrorCode::HandoffInProgress
        );
        assert!(state.handoff_in_flight.try_write().is_ok());
    }

    #[tokio::test]
    async fn a_dropped_fenced_request_releases_its_admission() {
        let state = test_state(false);
        let controller = state.controller.lock().await;
        let in_flight = spawn_request(&state, held_fenced_request());
        wait_for_admitted_request(&state).await;
        // The connection goes away mid-handler.
        in_flight.abort();
        assert!(in_flight.await.unwrap_err().is_cancelled());
        assert!(state.handoff_in_flight.try_write().is_ok());
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(attempt.fence().await, Ok(()));
        attempt.cancel(HandoffCancelReason::Requested).await;
        drop(controller);
    }

    /// A consent prompt runs through `outside`: the fence goes up while the
    /// prompt is open, and the retaken admission then reads `Fenced`.
    #[tokio::test]
    async fn a_wait_outside_the_admission_lets_the_fence_go_up() {
        let state = test_state(false);
        let (admitted, admitted_signal) = tokio::sync::oneshot::channel();
        let (answer, answer_signal) = tokio::sync::oneshot::channel::<bool>();
        let prompt = tokio::spawn({
            let state = Arc::clone(&state);
            async move {
                let request = held_fenced_request();
                let mut admission = HandoffAdmission::for_request(&request, &state)
                    .await
                    .unwrap();
                admitted.send(()).unwrap();
                let answered = admission.outside(answer_signal).await.unwrap();
                // Retaken: a later fence would have to wait for this handler.
                let retaken = state.handoff_in_flight.try_write().is_err();
                let fenced = refuse_while_fenced(&state).map_err(|error| error.code);
                drop(admission);
                (answered, retaken, fenced)
            }
        });
        admitted_signal.await.unwrap();
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(
            time::timeout(Duration::from_secs(1), attempt.fence())
                .await
                .expect("the fence never waits out an open prompt"),
            Ok(())
        );
        assert!(state.handoff_gate.is_fenced());
        assert!(!prompt.is_finished(), "the prompt is still open");
        answer.send(true).unwrap();
        let (answered, retaken, fenced) = time::timeout(Duration::from_secs(5), prompt)
            .await
            .expect("the admission is retaken once the fence released its guard")
            .unwrap();
        assert!(answered);
        assert!(retaken, "the admission is held again after the prompt");
        assert_eq!(fenced, Err(ErrorCode::HandoffInProgress));
        assert!(state.handoff_in_flight.try_write().is_ok());
        attempt.cancel(HandoffCancelReason::Requested).await;
    }

    /// A committed close releases its admission before its exit wait.
    #[tokio::test]
    async fn a_released_admission_no_longer_holds_the_fence_back() {
        let state = test_state(false);
        let request = held_fenced_request();
        let mut admission = HandoffAdmission::for_request(&request, &state)
            .await
            .unwrap();
        assert!(
            state.handoff_in_flight.try_write().is_err(),
            "a fenced admission holds the guard"
        );
        admission.release();
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(
            time::timeout(Duration::from_secs(1), attempt.fence())
                .await
                .expect("a released admission does not hold the fence back"),
            Ok(())
        );
        assert!(state.handoff_gate.is_fenced());
        // Still alive: only `release` freed the guard.
        drop(admission);
        attempt.cancel(HandoffCancelReason::Requested).await;
    }

    #[tokio::test]
    async fn launch_reservations_are_refused_until_the_gate_is_idle() {
        let state = test_state(false);
        drop(reserve_launch_slot(&state).await.unwrap());
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(
            reserve_launch_slot(&state).await.err().unwrap().code,
            ErrorCode::HandoffInProgress
        );
        attempt.fence().await.unwrap();
        assert_eq!(
            reserve_launch_slot(&state).await.err().unwrap().code,
            ErrorCode::HandoffInProgress
        );
        attempt.cancel(HandoffCancelReason::Requested).await;
        drop(reserve_launch_slot(&state).await.unwrap());
    }

    #[tokio::test]
    async fn the_fence_holds_the_topology_permit_and_fences_unused_close_until_cancel() {
        let state = test_state(false);
        let lair = Lair::new("durable", PathBuf::from("/tmp"));
        let dojo_id = lair.dojos[0].id;
        {
            let mut topology = state.topology.write().await;
            let revision = topology.revision();
            topology.insert_lair_at(revision, lair).unwrap();
        }
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert!(
            state.topology_transactions.try_acquire().is_ok(),
            "preparing does not hold the permit"
        );
        attempt.fence().await.unwrap();
        assert!(state.topology_transactions.try_acquire().is_err());
        // Even past the request choke point, an unused-close claim waits for
        // the permit the fence holds (Plan 0061 D13).
        let peer = PeerIdentity::for_test();
        let authorization = RequestAuthorizationContext::default();
        let mut admission = HandoffAdmission::unfenced();
        let close = handle_authorized_request(
            Request::CloseUnusedDojo { dojo_id },
            &state,
            &peer,
            1,
            false,
            false,
            &authorization,
            &mut admission,
        );
        tokio::pin!(close);
        assert!(
            time::timeout(Duration::from_millis(100), &mut close)
                .await
                .is_err(),
            "the unused close cannot run under the fence"
        );
        attempt.cancel(HandoffCancelReason::Requested).await;
        let closed = time::timeout(Duration::from_secs(5), close)
            .await
            .expect("the unused close runs once the fence lifts")
            .unwrap();
        assert!(matches!(closed.response, Response::UnusedDojoClose { .. }));
        assert!(state.topology_transactions.try_acquire().is_ok());
    }

    #[tokio::test]
    async fn a_transient_lair_under_the_fence_cancels_the_handoff_as_blocked() {
        let state = test_state(false);
        let report = gated_handoff_report(&state).await;
        // The transient Lair opens after the report, before the fence.
        let transient = Lair::transient("transient", PathBuf::from("/tmp"));
        let transient_id = transient.id;
        {
            let mut topology = state.topology.write().await;
            let revision = topology.revision();
            topology.insert_lair_at(revision, transient).unwrap();
        }
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(
            fence_for_handoff(&mut attempt).await,
            Err(HandoffCancelReason::Blocked)
        );
        attempt.cancel(HandoffCancelReason::Blocked).await;

        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let error = execute_with_forward_prepared(&state, &report).await;
        assert_eq!(error.code, ErrorCode::HandoffUnavailable);
        assert_eq!(
            error.handoff_blocking_reasons[0],
            splinterm_protocol::HandoffBlockingReason::TransientLairsOpen {
                count: 1,
                lair_ids: vec![transient_id],
            }
        );
        assert_eq!(
            handoff_status_phases(&mut subscription),
            [
                HandoffStatusPhase::Preparing,
                HandoffStatusPhase::Fenced,
                cancelled(HandoffCancelReason::Blocked),
            ]
        );
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
        assert!(state.topology_transactions.try_acquire().is_ok());
    }

    #[tokio::test(start_paused = true)]
    async fn a_retiring_splint_past_the_drain_deadline_cancels_the_handoff_as_timed_out() {
        let state = test_state(false);
        let report = gated_handoff_report(&state).await;
        let retiring = state.retiring.tasks.spawn(std::future::pending::<()>());
        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let error = execute_with_forward_prepared(&state, &report).await;
        assert_eq!(error.code, ErrorCode::HandoffUnavailable);
        assert_eq!(
            handoff_status_phases(&mut subscription),
            [
                HandoffStatusPhase::Preparing,
                HandoffStatusPhase::Fenced,
                cancelled(HandoffCancelReason::TimedOut),
            ]
        );
        // Nothing was killed, and the tracker is open again.
        assert!(!retiring.is_finished());
        assert!(!state.retiring.tasks.is_closed());
        assert_eq!(state.handoff_gate.phase(), HandoffGatePhase::Idle);
        retiring.abort();
        // Once the Splint is reaped the drain completes at once.
        while !state.retiring.tasks.is_empty() {
            tokio::task::yield_now().await;
        }
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        assert_eq!(fence_for_handoff(&mut attempt).await, Ok(()));
        attempt.cancel(HandoffCancelReason::Failed).await;
    }

