    #[tokio::test]
    async fn a_request_dropped_during_held_work_keeps_the_fence_until_the_work_ends() {
        let state = test_state(false);
        let mut subscription = state.topology_hub.lock().await.subscribe(1, 41);
        let (started, started_signal) = tokio::sync::oneshot::channel();
        let (finish, finish_signal) = tokio::sync::oneshot::channel::<()>();
        let caller = tokio::spawn({
            let state = Arc::clone(&state);
            async move {
                let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
                attempt.fence().await.unwrap();
                // Stands in for the fence's metadata save.
                let _ = attempt
                    .run_held(async move {
                        started.send(()).unwrap();
                        let _ = finish_signal.await;
                    })
                    .await;
                attempt.cancel(HandoffCancelReason::Failed).await;
            }
        });
        started_signal.await.unwrap();
        // The initiating connection goes away mid-save.
        caller.abort();
        assert!(caller.await.unwrap_err().is_cancelled());
        for _ in 0..16 {
            tokio::task::yield_now().await;
        }
        assert!(
            state.handoff_gate.is_fenced(),
            "the running work keeps the gate fenced"
        );
        assert!(
            state.topology_transactions.try_acquire().is_err(),
            "no transaction can overtake the running work"
        );
        assert_eq!(
            HandoffAttempt::begin(&state).await.err().unwrap().code,
            ErrorCode::HandoffInProgress
        );
        finish.send(()).unwrap();
        wait_for_idle_gate(&state).await;
        let mut phases = Vec::new();
        time::timeout(Duration::from_secs(5), async {
            loop {
                phases.extend(handoff_status_phases(&mut subscription));
                if phases.last() == Some(&cancelled(HandoffCancelReason::Requested)) {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the work's end cancels the orphaned attempt");
        assert_eq!(
            phases,
            [
                HandoffStatusPhase::Preparing,
                HandoffStatusPhase::Fenced,
                cancelled(HandoffCancelReason::Requested),
            ]
        );
        assert!(state.topology_transactions.try_acquire().is_ok());
    }

    #[tokio::test]
    async fn a_policy_reload_waits_for_the_permit_off_the_serve_loop_and_coalesces() {
        let state = test_state(false);
        let generation = || async { state.policy.lock().await.snapshot().id };
        let before = generation().await;
        let start = || tokio::spawn(apply_policy_reload(Arc::clone(&state)));
        // A fence, or any long transaction, holds the permit.
        let fence = state.topology_transactions.acquire().await.unwrap();
        let mut queue = PolicyReloadQueue::default();
        // Each signal returns to the serve loop at once.
        for _ in 0..3 {
            queue.request(start);
        }
        assert!(queue.is_running() && queue.queued);
        assert!(
            time::timeout(Duration::from_millis(50), queue.finished())
                .await
                .is_err(),
            "the reload waits for the permit"
        );
        assert_eq!(generation().await, before);
        drop(fence);
        let finished = time::timeout(Duration::from_secs(5), queue.finished())
            .await
            .unwrap();
        queue.complete(finished, start).unwrap();
        assert_eq!(generation().await, before + 1);
        assert!(
            queue.is_running() && !queue.queued,
            "the queued reload starts"
        );
        let finished = time::timeout(Duration::from_secs(5), queue.finished())
            .await
            .unwrap();
        queue.complete(finished, start).unwrap();
        assert!(!queue.is_running());
        assert_eq!(generation().await, before + 2, "three signals, two reloads");

        // Shutdown lets a running reload finish and drops a queued one.
        queue.request(start);
        queue.request(start);
        time::timeout(Duration::from_secs(5), queue.drain())
            .await
            .unwrap()
            .unwrap();
        assert!(!queue.is_running() && !queue.queued);
        assert_eq!(generation().await, before + 3);
    }

    // ---- ADR 0014 consent and pending lifecycle (Plan 0053 PR 3) ----

    /// Routes every workspace prompt the daemon shows to the test, in place
    /// of the trusted consent client.
    fn script_prompts(state: &DaemonState) -> tokio::sync::mpsc::UnboundedReceiver<ScriptedPrompt> {
        let (prompts, receiver) = tokio::sync::mpsc::unbounded_channel();
        *state.consent_script.lock().unwrap() = Some(prompts);
        receiver
    }

    async fn next_scripted_prompt(
        prompts: &mut tokio::sync::mpsc::UnboundedReceiver<ScriptedPrompt>,
    ) -> ScriptedPrompt {
        time::timeout(Duration::from_secs(5), prompts.recv())
            .await
            .expect("a prompt is shown")
            .expect("the prompter is running")
    }

    /// `peer` with this process's start time, as connection verification
    /// records it.
    fn with_start_time(mut peer: PeerIdentity) -> PeerIdentity {
        peer.install_start_time(
            agent_status::process_start_time(std::process::id()).expect("own start time"),
        );
        peer
    }

    async fn insert_test_lair(state: &DaemonState, name: &str) -> LairId {
        let lair = Lair::new(name, PathBuf::from("/tmp"));
        let lair_id = lair.id;
        let mut topology = state.topology.write().await;
        let revision = topology.revision();
        topology.insert_lair_at(revision, lair).unwrap();
        lair_id
    }

    fn lair_request(lair_id: LairId, scopes: &[AccessScope], wait_millis: u32) -> Request {
        Request::RequestLairAccess {
            lair_id,
            level: None,
            scopes: scopes.to_vec(),
            wait_millis,
            agent_name: Some("Test agent".to_owned()),
        }
    }

    async fn ask(
        state: &Arc<DaemonState>,
        peer: &PeerIdentity,
        request: Request,
    ) -> Result<Response, ProtocolError> {
        handle_request(request, state, peer, 1, 0, false, false)
            .await
            .map(|handled| handled.response)
    }

    fn spawn_ask(
        state: &Arc<DaemonState>,
        peer: &PeerIdentity,
        request: Request,
    ) -> tokio::task::JoinHandle<Result<Response, ProtocolError>> {
        let state = Arc::clone(state);
        let peer = peer.clone();
        tokio::spawn(async move { ask(&state, &peer, request).await })
    }

    fn pending_request_id(response: &Response) -> u64 {
        match response {
            Response::LairAccessPending { request_id, .. } => *request_id,
            other => panic!("not pending: {other:?}"),
        }
    }

    fn granted(response: Response) -> splinterm_protocol::LairAccessGrant {
        match response {
            Response::LairAccessGranted { grant, .. } => grant,
            other => panic!("not granted: {other:?}"),
        }
    }

    async fn wait_until_no_request_is_pending(state: &DaemonState) {
        time::timeout(Duration::from_secs(5), async {
            while state.pending_access.len() != 0 {
                time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the pending request ends");
    }

    async fn has_once_grant(state: &DaemonState, peer: &PeerIdentity, lair_id: LairId) -> bool {
        state
            .grants
            .lock()
            .await
            .authorize_lair(peer, lair_id, &[AccessScope::Observe])
            .is_some()
    }

    #[tokio::test]
    async fn a_request_a_grant_covers_is_answered_without_a_prompt() {
        let fixture = agent_fixture().await;
        let mut prompts = script_prompts(&fixture.state);
        let session = fixture
            .commit(
                &fixture.peer,
                agent_access::AccessSet::Level(agent_access::AccessLevel::LookAndType),
                agent_access::GrantDuration::WorkspaceSession,
            )
            .await
            .unwrap();
        let grant = granted(
            ask(
                &fixture.state,
                &fixture.peer,
                Request::RequestLairAccess {
                    lair_id: fixture.lair_id,
                    level: Some(splinterm_protocol::AccessLevel::Look),
                    scopes: Vec::new(),
                    wait_millis: 0,
                    agent_name: None,
                },
            )
            .await
            .unwrap(),
        );
        assert_eq!(
            grant.source,
            splinterm_protocol::AccessGrantSource::WorkspaceSession
        );
        assert_eq!(grant.grant_id, session.grant_id);
        assert_eq!(grant.expires_at_unix_seconds, 0);
        // The while-open Look and type grant does not cover renaming; the
        // remembered Manage grant does, as an independent source.
        let remembered = fixture
            .commit(
                &fixture.peer,
                agent_access::AccessSet::Level(agent_access::AccessLevel::Manage),
                agent_access::GrantDuration::Remembered,
            )
            .await
            .unwrap();
        let grant = granted(
            ask(
                &fixture.state,
                &fixture.peer,
                lair_request(fixture.lair_id, &[AccessScope::TopologyName], 0),
            )
            .await
            .unwrap(),
        );
        assert_eq!(
            grant.source,
            splinterm_protocol::AccessGrantSource::Remembered
        );
        assert_eq!(grant.grant_id, remembered.grant_id);
        assert!(prompts.try_recv().is_err(), "no prompt was shown");
        assert_eq!(fixture.state.pending_access.len(), 0);
    }

    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "one request's whole pending, join, answer, and collection path"
    )]
    async fn the_wait_budget_replies_pending_and_a_repeat_joins_without_a_second_prompt() {
        use splinterm_protocol::{DurationWithheld, GrantDuration};

        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let scopes = [AccessScope::Observe, AccessScope::Input];
        let first = ask(&state, &peer, lair_request(lair_id, &scopes, 0))
            .await
            .unwrap();
        let request_id = pending_request_id(&first);
        let Response::LairAccessPending {
            expires_at_unix_seconds,
            lair_id: pending_lair,
            ..
        } = first
        else {
            unreachable!()
        };
        assert_eq!(pending_lair, lair_id);
        let now = unix_seconds_now();
        assert!((now + 118..=now + 121).contains(&expires_at_unix_seconds));
        let prompt = next_scripted_prompt(&mut prompts).await;
        assert_eq!(prompt.request_id, request_id);
        assert_eq!(prompt.lair_name, "agents");
        assert_eq!(prompt.details.level, None, "two scopes are Custom");
        assert_eq!(prompt.details.agent_name.as_deref(), Some("Test agent"));
        // Without a pinned identity only "Just this once" is offered; the
        // others are shown withheld, with the reason.
        assert_eq!(
            prompt
                .details
                .durations
                .iter()
                .map(|offer| (offer.duration, offer.withheld))
                .collect::<Vec<_>>(),
            [
                (GrantDuration::Once, None),
                (
                    GrantDuration::WorkspaceSession,
                    Some(DurationWithheld::NoPinnedIdentity)
                ),
                (
                    GrantDuration::Remembered,
                    Some(DurationWithheld::NoPinnedIdentity)
                ),
            ]
        );
        // A repeat joins: the same request, and no second prompt.
        let joined = ask(&state, &peer, lair_request(lair_id, &scopes, 20))
            .await
            .unwrap();
        assert_eq!(pending_request_id(&joined), request_id);
        assert!(prompts.try_recv().is_err(), "one prompt per request");
        // A call still waiting receives the answer directly.
        let waiting = spawn_ask(&state, &peer, lair_request(lair_id, &scopes, 5_000));
        time::sleep(Duration::from_millis(50)).await;
        prompt
            .answer
            .send(ConsentDecision::Grant {
                duration: GrantDuration::Once,
            })
            .unwrap();
        let grant = granted(waiting.await.unwrap().unwrap());
        assert_eq!(
            grant.source,
            splinterm_protocol::AccessGrantSource::Ephemeral
        );
        assert_eq!(grant.scopes, scopes);
        assert_ne!(grant.expires_at_unix_seconds, 0);
        wait_until_no_request_is_pending(&state).await;
        // Later repeats are covered by the grant and answered at once.
        let again = granted(
            ask(&state, &peer, lair_request(lair_id, &scopes, 0))
                .await
                .unwrap(),
        );
        assert_eq!(again.grant_id, grant.grant_id);
        assert!(prompts.try_recv().is_err());
    }

    #[tokio::test]
    async fn cancelling_closes_the_prompt_and_a_late_answer_grants_nothing() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let scopes = [AccessScope::Observe];
        let request_id = pending_request_id(
            &ask(&state, &peer, lair_request(lair_id, &scopes, 0))
                .await
                .unwrap(),
        );
        let prompt = next_scripted_prompt(&mut prompts).await;
        // Different access while one is pending fails, naming it.
        let refused = ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe, AccessScope::Input], 0),
        )
        .await
        .unwrap_err();
        assert_eq!(refused.code, ErrorCode::ResourceLimit);
        assert_eq!(refused.pending_request_id, Some(request_id));
        assert_eq!(
            ask(
                &state,
                &peer,
                Request::CancelLairAccessRequest {
                    lair_id,
                    request_id: request_id + 100,
                },
            )
            .await
            .unwrap_err()
            .code,
            ErrorCode::NotFound
        );
        assert_eq!(
            ask(
                &state,
                &peer,
                Request::CancelLairAccessRequest {
                    lair_id,
                    request_id,
                }
            )
            .await
            .unwrap(),
            Response::LairAccessRequestCancelled {
                lair_id,
                topology_revision: state.topology.read().await.revision(),
                request_id,
            }
        );
        // The prompt closed, so its answer reaches nothing and grants
        // nothing.
        let _ = prompt.answer.send(ConsentDecision::Grant {
            duration: splinterm_protocol::GrantDuration::Once,
        });
        time::sleep(Duration::from_millis(50)).await;
        assert!(!has_once_grant(&state, &peer, lair_id).await);
        // Cancelling is not a deny: asking again opens a new prompt.
        let again = pending_request_id(
            &ask(&state, &peer, lair_request(lair_id, &scopes, 0))
                .await
                .unwrap(),
        );
        assert_ne!(again, request_id);
        assert_eq!(next_scripted_prompt(&mut prompts).await.request_id, again);
    }

    #[tokio::test]
    async fn a_deny_is_collected_once_and_then_cools_the_agent_down() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let scopes = [AccessScope::Observe];
        ask(&state, &peer, lair_request(lair_id, &scopes, 0))
            .await
            .unwrap();
        next_scripted_prompt(&mut prompts)
            .await
            .answer
            .send(ConsentDecision::Deny)
            .unwrap();
        wait_until_no_request_is_pending(&state).await;
        let code = |result: Result<Response, ProtocolError>| result.unwrap_err().code;
        assert_eq!(
            code(ask(&state, &peer, lair_request(lair_id, &scopes, 0)).await),
            ErrorCode::ConsentDenied,
            "the requester collects its deny"
        );
        assert_eq!(
            code(ask(&state, &peer, lair_request(lair_id, &scopes, 0)).await),
            ErrorCode::RateLimited,
        );
        assert_eq!(
            code(
                ask(
                    &state,
                    &peer,
                    lair_request(lair_id, &[AccessScope::Input], 0)
                )
                .await
            ),
            ErrorCode::RateLimited,
            "the cooldown covers the identity and workspace, not one request"
        );
        assert!(prompts.try_recv().is_err(), "the prompt does not reopen");
        assert!(!has_once_grant(&state, &peer, lair_id).await);
    }

    #[tokio::test]
    async fn a_workspace_ending_while_pending_ends_the_request() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        let prompt = next_scripted_prompt(&mut prompts).await;
        end_lair_grants(&state, lair_id, "test workspace end").await;
        assert_eq!(
            time::timeout(Duration::from_secs(5), waiting)
                .await
                .unwrap()
                .unwrap()
                .unwrap_err()
                .code,
            ErrorCode::NotFound
        );
        let _ = prompt.answer.send(ConsentDecision::Grant {
            duration: splinterm_protocol::GrantDuration::Once,
        });
        time::sleep(Duration::from_millis(50)).await;
        assert!(!has_once_grant(&state, &peer, lair_id).await);
        assert_eq!(state.pending_access.len(), 0);
    }

    /// The fence never waits for a call waiting on the person, and nothing
    /// pending survives it (ADR 0011 and 0014).
    #[tokio::test]
    async fn the_handoff_fence_ends_pending_requests_without_waiting_for_them() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 20_000),
        );
        let prompt = next_scripted_prompt(&mut prompts).await;
        let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
        time::timeout(Duration::from_secs(1), attempt.fence())
            .await
            .expect("the fence never waits out a pending request")
            .unwrap();
        assert_eq!(
            time::timeout(Duration::from_secs(5), waiting)
                .await
                .unwrap()
                .unwrap()
                .unwrap_err()
                .code,
            ErrorCode::HandoffInProgress
        );
        let _ = prompt.answer.send(ConsentDecision::Grant {
            duration: splinterm_protocol::GrantDuration::Once,
        });
        time::sleep(Duration::from_millis(50)).await;
        assert!(!has_once_grant(&state, &peer, lair_id).await);
        assert_eq!(state.pending_access.len(), 0);
        // New requests are refused while fenced.
        assert_eq!(
            ask(
                &state,
                &peer,
                lair_request(lair_id, &[AccessScope::Observe], 0)
            )
            .await
            .unwrap_err()
            .code,
            ErrorCode::HandoffInProgress
        );
        attempt.cancel(HandoffCancelReason::Requested).await;
    }

    #[tokio::test]
    async fn revoke_all_access_cancels_every_pending_request() {
        let state = test_state(false);
        let first = insert_test_lair(&state, "first").await;
        let second = insert_test_lair(&state, "second").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        for lair_id in [first, second] {
            ask(
                &state,
                &peer,
                lair_request(lair_id, &[AccessScope::Observe], 0),
            )
            .await
            .unwrap();
        }
        let shown = next_scripted_prompt(&mut prompts).await;
        // Only the trusted UI may end every pending request.
        assert_eq!(
            ask(&state, &peer, Request::CancelAllLairAccessRequests)
                .await
                .unwrap_err()
                .code,
            ErrorCode::Unauthorized
        );
        assert_eq!(state.pending_access.cancel_all(), 2);
        let _ = shown.answer.send(ConsentDecision::Grant {
            duration: splinterm_protocol::GrantDuration::Once,
        });
        time::sleep(Duration::from_millis(50)).await;
        for lair_id in [first, second] {
            assert!(!has_once_grant(&state, &peer, lair_id).await);
        }
        assert!(prompts.try_recv().is_err(), "the queued prompt never shows");
    }

    fn sleeping_child() -> (std::process::Child, std::os::fd::OwnedFd, (u64, u64)) {
        let child = std::process::Command::new("sleep")
            .arg("30")
            .spawn()
            .expect("spawn a sleeping child");
        let pid = rustix::process::Pid::from_raw(i32::try_from(child.id()).unwrap()).unwrap();
        let pidfd = rustix::process::pidfd_open(pid, rustix::process::PidfdFlags::empty()).unwrap();
        let executing = consent::executable_file_identity(child.id()).unwrap();
        (child, pidfd, executing)
    }

    #[tokio::test]
    async fn a_pending_request_ends_when_its_process_exits() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let (mut child, pidfd, executing) = sleeping_child();
        let admitted = state
            .pending_access
            .admit(
                &peer,
                lair_id,
                vec![AccessScope::Observe],
                None,
                Instant::now(),
                |_| Ok(pending_access::PinnedRequester { pidfd, executing }),
            )
            .unwrap();
        let mut outcome = admitted.outcome.clone();
        watch_pending_request(
            &state,
            admitted.request_id,
            admitted.expires,
            admitted.opened.unwrap(),
        );
        child.kill().unwrap();
        child.wait().unwrap();
        let ended = time::timeout(Duration::from_secs(5), outcome.wait_for(Option::is_some))
            .await
            .expect("the exit ends the request")
            .unwrap()
            .clone();
        assert!(matches!(
            ended,
            Some(pending_access::Outcome::Failed(error)) if error.code == ErrorCode::Cancelled
        ));
        assert_eq!(state.pending_access.len(), 0);
    }

    #[tokio::test]
    async fn an_answer_commits_only_for_a_live_requester_and_an_offered_duration() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let process = pending_access::ProcessKey::of(&peer).unwrap();
        let scopes = vec![AccessScope::Observe];
        let admit = |pin: pending_access::PinnedRequester| {
            state
                .pending_access
                .admit(&peer, lair_id, scopes.clone(), None, Instant::now(), |_| {
                    Ok(pin)
                })
                .unwrap()
        };
        let settled = |admitted: &pending_access::Admitted| admitted.outcome.borrow().clone();
        // The pinned process exited before the answer: nothing commits.
        let (mut child, pidfd, executing) = sleeping_child();
        let gone = admit(pending_access::PinnedRequester { pidfd, executing });
        child.kill().unwrap();
        child.wait().unwrap();
        let job = state.pending_access.next_prompt().unwrap();
        settle_lair_prompt(
            &state,
            job,
            Ok(ConsentDecision::Grant {
                duration: splinterm_protocol::GrantDuration::Once,
            }),
            remote_consent::AnswerRoute::Local,
        )
        .await;
        assert!(matches!(
            settled(&gone),
            Some(pending_access::Outcome::Failed(error)) if error.code == ErrorCode::Cancelled
        ));
        assert!(!has_once_grant(&state, &peer, lair_id).await);
        // A duration the requester is not offered commits nothing.
        let offered_once = admit(open_requester_pidfd(&process).unwrap());
        let job = state.pending_access.next_prompt().unwrap();
        settle_lair_prompt(
            &state,
            job,
            Ok(ConsentDecision::Grant {
                duration: splinterm_protocol::GrantDuration::Remembered,
            }),
            remote_consent::AnswerRoute::Local,
        )
        .await;
        assert!(matches!(
            settled(&offered_once),
            Some(pending_access::Outcome::Failed(error))
                if error.code == ErrorCode::ConsentUnavailable
        ));
        assert!(!has_once_grant(&state, &peer, lair_id).await);
        // The live requester with an offered duration is granted.
        let live = admit(open_requester_pidfd(&process).unwrap());
        let job = state.pending_access.next_prompt().unwrap();
        settle_lair_prompt(
            &state,
            job,
            Ok(ConsentDecision::Grant {
                duration: splinterm_protocol::GrantDuration::Once,
            }),
            remote_consent::AnswerRoute::Local,
        )
        .await;
        assert!(matches!(
            settled(&live),
            Some(pending_access::Outcome::Granted(response))
                if matches!(*response, Response::LairAccessGranted { .. })
        ));
        assert!(has_once_grant(&state, &peer, lair_id).await);
    }

    /// F1: an answer committing while the fence is up grants nothing; the
    /// commit holds the handoff admission and checks the fence under it.
    #[tokio::test]
    async fn an_answer_under_the_handoff_fence_commits_nothing() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let process = pending_access::ProcessKey::of(&peer).unwrap();
        let admitted = state
            .pending_access
            .admit(
                &peer,
                lair_id,
                vec![AccessScope::Observe],
                None,
                Instant::now(),
                |_| open_requester_pidfd(&process),
            )
            .unwrap();
        let job = state.pending_access.next_prompt().unwrap();
        // The gate reads fenced, as after a fence that has not yet ended
        // this request.
        state.handoff_gate.set(HandoffGatePhase::Fenced);
        settle_lair_prompt(
            &state,
            job,
            Ok(ConsentDecision::Grant {
                duration: splinterm_protocol::GrantDuration::Once,
            }),
            remote_consent::AnswerRoute::Local,
        )
        .await;
        state.handoff_gate.set(HandoffGatePhase::Idle);
        assert!(matches!(
            &*admitted.outcome.borrow(),
            Some(pending_access::Outcome::Failed(error))
                if error.code == ErrorCode::HandoffInProgress
        ));
        assert!(!has_once_grant(&state, &peer, lair_id).await);
        assert_eq!(state.pending_access.len(), 0);
    }

    #[tokio::test]
    async fn without_a_trusted_session_a_request_fails_closed_at_once() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        // No script: the daemon launches its installed client, which the
        // test prefix does not hold.
        let failed = time::timeout(
            Duration::from_secs(5),
            ask(
                &state,
                &peer,
                lair_request(lair_id, &[AccessScope::Observe], 20_000),
            ),
        )
        .await
        .expect("the failure does not wait out the budget")
        .unwrap_err();
        assert_eq!(failed.code, ErrorCode::ConsentUnavailable);
        assert_eq!(state.pending_access.len(), 0);
    }

    // ---- ADR 0015 remote consent routing (Plan 0066 M4) ----

    /// A daemon with no graphical session of its own.
    fn headless(mut state: Arc<DaemonState>) -> Arc<DaemonState> {
        Arc::get_mut(&mut state)
            .expect("the state is not shared yet")
            .local_consent_display = false;
        state
    }

    /// A consent responder, a remote Window or a terminal approver,
    /// subscribed as the daemon serves one, with its `/proc` checks passed.
    struct TestResponder {
        connection_id: u64,
        peer: PeerIdentity,
        /// A terminal approver, as the installed client; otherwise a remote
        /// Window, as the relay.
        terminal: bool,
        events: tokio::sync::mpsc::Receiver<splinterm_protocol::SubscriptionEvent>,
        guard: Option<remote_consent::ResponderGuard>,
    }

    impl TestResponder {
        /// A remote Window in a relay process of its own.
        async fn subscribe(state: &Arc<DaemonState>, connection_id: u64) -> Self {
            let mut peer = PeerIdentity::for_test();
            peer.pid = 20_000 + u32::try_from(connection_id).unwrap();
            Self::subscribe_as(state, connection_id, peer, false).await
        }

        /// A terminal approver: the installed client, here this test
        /// process as the pinned snapshot.
        async fn subscribe_terminal(state: &Arc<DaemonState>, connection_id: u64) -> Self {
            let pinned = Arc::new(consent::PinnedClientSnapshot::own_executable_for_test());
            Self::subscribe_as(state, connection_id, pinned_window_peer(&pinned), true).await
        }

        async fn subscribe_as(
            state: &Arc<DaemonState>,
            connection_id: u64,
            peer: PeerIdentity,
            terminal: bool,
        ) -> Self {
            use splinterm_protocol::ConsentResponderKind;

            state.consent_responders.set_probe(Arc::new(|_, _| Ok(())));
            let kind = if terminal {
                ConsentResponderKind::Terminal
            } else {
                ConsentResponderKind::Window
            };
            let handled = handle_request(
                Request::SubscribeConsentOffers { kind },
                state,
                &peer,
                connection_id,
                0,
                terminal,
                !terminal,
            )
            .await
            .unwrap();
            let Some(PendingSubscription::ConsentOffers { stream }) = handled.subscription else {
                panic!("a consent responder subscribes");
            };
            let (events, guard) = stream.into_parts();
            Self {
                connection_id,
                peer,
                terminal,
                events,
                guard: Some(guard),
            }
        }

        async fn next(&mut self) -> splinterm_protocol::SubscriptionEvent {
            time::timeout(Duration::from_secs(5), self.events.recv())
                .await
                .expect("an event arrives")
                .expect("the subscription runs")
        }

        async fn offer(&mut self) -> splinterm_protocol::ConsentOffer {
            match self.next().await {
                splinterm_protocol::SubscriptionEvent::ConsentOffered { offer } => offer,
                other => panic!("expected an offer, got {other:?}"),
            }
        }

        async fn withdrawn(&mut self) -> (u64, splinterm_protocol::ConsentOfferEnd) {
            match self.next().await {
                splinterm_protocol::SubscriptionEvent::ConsentOfferWithdrawn {
                    offer_id,
                    reason,
                } => (offer_id, reason),
                other => panic!("expected a withdrawal, got {other:?}"),
            }
        }

        fn quiet(&mut self) -> bool {
            self.events.try_recv().is_err()
        }

        async fn answer(
            &self,
            state: &Arc<DaemonState>,
            offer: &splinterm_protocol::ConsentOffer,
            decision: ConsentDecision,
        ) -> Result<Response, ProtocolError> {
            handle_request(
                Request::AnswerConsentOffer {
                    daemon_generation: offer.daemon_generation,
                    offer_id: offer.offer_id,
                    nonce: offer.nonce,
                    decision,
                },
                state,
                &self.peer,
                self.connection_id,
                1,
                self.terminal,
                !self.terminal,
            )
            .await
            .map(|handled| handled.response)
        }

        /// The Window closes: its connection ends the responder.
        fn close(&mut self) {
            self.guard = None;
        }
    }

    const ONCE: ConsentDecision = ConsentDecision::Grant {
        duration: splinterm_protocol::GrantDuration::Once,
    };

    async fn finished(
        waiting: tokio::task::JoinHandle<Result<Response, ProtocolError>>,
    ) -> Result<Response, ProtocolError> {
        time::timeout(Duration::from_secs(5), waiting)
            .await
            .expect("the request finishes")
            .unwrap()
    }

    #[tokio::test]
    async fn a_headless_daemon_with_no_responder_is_unavailable_at_once() {
        let state = headless(test_state(false));
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let failed = time::timeout(
            Duration::from_secs(5),
            ask(
                &state,
                &peer,
                lair_request(lair_id, &[AccessScope::Observe], 20_000),
            ),
        )
        .await
        .expect("the failure does not wait out the budget")
        .unwrap_err();
        assert_eq!(failed.code, ErrorCode::ConsentUnavailable);
        assert_eq!(failed.message, remote_consent::NO_ROUTE);
        assert!(prompts.try_recv().is_err(), "no local dialog is shown");
        assert_eq!(state.pending_access.len(), 0);
    }

    #[tokio::test]
    async fn a_headless_prompt_goes_to_its_responders_until_the_last_one_closes() {
        let state = headless(test_state(false));
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let mut first = TestResponder::subscribe(&state, 11).await;
        let mut second = TestResponder::subscribe(&state, 12).await;
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        let lost = first.offer().await;
        let kept = second.offer().await;
        assert_ne!(lost.offer_id, kept.offer_id);
        assert_ne!(lost.nonce, kept.nonce);
        assert!(prompts.try_recv().is_err(), "no local dialog is shown");
        // One Window closing takes only its own offer.
        first.close();
        time::sleep(Duration::from_millis(50)).await;
        assert!(second.quiet());
        assert_eq!(state.pending_access.len(), 1, "the request still waits");
        // The last one closing leaves no route.
        second.close();
        let failed = finished(waiting).await.unwrap_err();
        assert_eq!(failed.code, ErrorCode::ConsentUnavailable);
        assert_eq!(failed.message, remote_consent::ROUTES_CLOSED);
        assert_eq!(state.pending_access.len(), 0);
        assert!(!has_once_grant(&state, &peer, lair_id).await);
    }

    #[tokio::test]
    async fn a_remote_answer_wins_over_the_local_dialog_and_the_other_offers() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let mut winner = TestResponder::subscribe(&state, 11).await;
        let mut loser = TestResponder::subscribe(&state, 12).await;
        let mut terminal = TestResponder::subscribe_terminal(&state, 13).await;
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        // Every route shows the prompt at once.
        let mut local = next_scripted_prompt(&mut prompts).await;
        let offer = winner.offer().await;
        let other = loser.offer().await;
        let in_terminal = terminal.offer().await;
        assert_eq!(offer.request_id, local.request_id);
        assert_eq!(in_terminal.request_id, local.request_id);
        assert!(offer.prompt.offers(splinterm_protocol::GrantDuration::Once));
        assert_eq!(
            winner.answer(&state, &offer, ONCE).await,
            Ok(Response::ConsentOfferAnswered)
        );
        let grant = granted(finished(waiting).await.unwrap());
        assert_eq!(
            grant.source,
            splinterm_protocol::AccessGrantSource::Ephemeral
        );
        for (responder, offer) in [(&mut loser, &other), (&mut terminal, &in_terminal)] {
            assert_eq!(
                responder.withdrawn().await,
                (
                    offer.offer_id,
                    splinterm_protocol::ConsentOfferEnd::AnsweredElsewhere
                )
            );
        }
        // The local dialog is closed.
        time::timeout(Duration::from_secs(5), local.answer.closed())
            .await
            .expect("the local dialog is killed");
        // A second answer, even the winner's again, finds nothing.
        for (responder, offer) in [
            (&winner, &offer),
            (&loser, &other),
            (&terminal, &in_terminal),
        ] {
            assert_eq!(
                responder
                    .answer(&state, offer, ONCE)
                    .await
                    .unwrap_err()
                    .code,
                ErrorCode::NotFound
            );
        }
        assert!(winner.quiet());
        wait_until_no_request_is_pending(&state).await;
    }

    #[tokio::test]
    async fn the_local_dialog_answering_first_withdraws_every_offer() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let mut responder = TestResponder::subscribe(&state, 11).await;
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        let local = next_scripted_prompt(&mut prompts).await;
        let offer = responder.offer().await;
        local.answer.send(ONCE).unwrap();
        granted(finished(waiting).await.unwrap());
        assert_eq!(
            responder.withdrawn().await,
            (
                offer.offer_id,
                splinterm_protocol::ConsentOfferEnd::AnsweredElsewhere
            )
        );
        assert_eq!(
            responder
                .answer(&state, &offer, ConsentDecision::Deny)
                .await
                .unwrap_err()
                .code,
            ErrorCode::NotFound
        );
    }

    #[tokio::test]
    async fn a_failed_local_dialog_drops_out_and_the_remote_route_still_answers() {
        let state = test_state(false);
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut prompts = script_prompts(&state);
        let mut responder = TestResponder::subscribe(&state, 11).await;
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        // The local dialog fails without an answer.
        drop(next_scripted_prompt(&mut prompts).await);
        let offer = responder.offer().await;
        time::sleep(Duration::from_millis(50)).await;
        assert_eq!(state.pending_access.len(), 1, "the request still waits");
        assert_eq!(
            responder
                .answer(&state, &offer, ConsentDecision::Deny)
                .await,
            Ok(Response::ConsentOfferAnswered)
        );
        assert_eq!(
            finished(waiting).await.unwrap_err().code,
            ErrorCode::ConsentDenied
        );
    }

    #[tokio::test]
    async fn a_terminal_approver_s_deny_is_audited_as_its_route() {
        let state = headless(test_state(false));
        let lair_id = insert_test_lair(&state, "agents").await;
        let peer = with_start_time(PeerIdentity::for_test());
        let mut approver = TestResponder::subscribe_terminal(&state, 11).await;
        let mut window = TestResponder::subscribe(&state, 12).await;
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        let offer = approver.offer().await;
        let other = window.offer().await;
        assert_eq!(
            approver.answer(&state, &offer, ConsentDecision::Deny).await,
            Ok(Response::ConsentOfferAnswered)
        );
        assert_eq!(
            finished(waiting).await.unwrap_err().code,
            ErrorCode::ConsentDenied
        );
        assert_eq!(
            window.withdrawn().await,
            (
                other.offer_id,
                splinterm_protocol::ConsentOfferEnd::AnsweredElsewhere
            )
        );
        // The answer is audited by route, never by nonce or decision.
        let page = state.audit.lock().await.page(None, 16);
        let [record] = page
            .records
            .iter()
            .filter(|record| {
                record.operation == splinterm_protocol::AuditOperation::AnswerConsentOffer
            })
            .collect::<Vec<_>>()[..]
        else {
            panic!("one answer audit record: {:?}", page.records);
        };
        assert_eq!(record.reason, "answered_in_terminal_approver");
        assert_eq!(
            record.outcome,
            Some(splinterm_protocol::AuditOutcome::Succeeded)
        );
        let encoded = serde_json::to_string(record).unwrap();
        let nonce = serde_json::to_string(&offer.nonce).unwrap();
        let nonce = nonce.trim_matches(|c| matches!(c, '[' | ']' | '"'));
        assert!(!encoded.contains(nonce), "{encoded}");
        wait_until_no_request_is_pending(&state).await;
    }

    #[tokio::test]
    async fn remote_answers_commit_every_duration_through_the_same_checks() {
        use splinterm_protocol::{AccessGrantSource, AccessLevel, GrantDuration};

        let mut fixture = agent_fixture().await;
        Arc::get_mut(&mut fixture.state)
            .expect("the state is not shared yet")
            .local_consent_display = false;
        let state = Arc::clone(&fixture.state);
        let peer = with_start_time(fixture.peer.clone());
        let mut responder = TestResponder::subscribe(&state, 11).await;
        let once = insert_test_lair(&state, "once").await;
        let open = insert_test_lair(&state, "open").await;
        for (lair_id, duration, source) in [
            (once, GrantDuration::Once, AccessGrantSource::Ephemeral),
            (
                open,
                GrantDuration::WorkspaceSession,
                AccessGrantSource::WorkspaceSession,
            ),
            (
                fixture.lair_id,
                GrantDuration::Remembered,
                AccessGrantSource::Remembered,
            ),
        ] {
            let waiting = spawn_ask(
                &state,
                &peer,
                Request::RequestLairAccess {
                    lair_id,
                    level: Some(AccessLevel::Look),
                    scopes: Vec::new(),
                    wait_millis: 5_000,
                    agent_name: None,
                },
            );
            let offer = responder.offer().await;
            assert!(offer.prompt.offers(duration), "{duration:?} is offered");
            assert_eq!(
                responder
                    .answer(&state, &offer, ConsentDecision::Grant { duration })
                    .await,
                Ok(Response::ConsentOfferAnswered)
            );
            let grant = granted(finished(waiting).await.unwrap());
            assert_eq!(grant.source, source, "{duration:?}");
            wait_until_no_request_is_pending(&state).await;
        }
        drop(fixture);
    }

    /// A responder whose connection stops reading its offers is dropped and
    /// its connection closed, so the client sees the end and can subscribe
    /// again instead of staying silently subscribed.
    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "one connection from Hello through its lagging subscription to its close"
    )]
    async fn a_responder_connection_that_stops_reading_is_closed() {
        time::timeout(Duration::from_secs(10), async {
            let state = headless(test_state(false));
            state.consent_responders.set_probe(Arc::new(|_, _| Ok(())));
            let pinned = Arc::new(consent::PinnedClientSnapshot::own_executable_for_test());
            let peer = pinned_window_peer(&pinned);
            let (mut client, server) = UnixStream::pair().unwrap();
            let (reader, _writer) = server.into_split();
            // One queued frame: past it the connection's writer is full.
            let (outbound, mut responses) = mpsc::channel(1);
            let (control, mut controls) = mpsc::channel(4);
            let (_closed, writer_closed) = watch::channel(false);
            let task_state = Arc::clone(&state);
            let task = tokio::spawn(async move {
                Box::pin(serve_authenticated(
                    reader,
                    &task_state,
                    &peer,
                    None,
                    41,
                    &outbound,
                    &control,
                    writer_closed,
                ))
                .await
            });
            for frame in [
                ClientFrame::Hello {
                    minimum_version: PROTOCOL_VERSION,
                    maximum_version: PROTOCOL_VERSION,
                    role: ClientRole::TrustedUi,
                    handoff_window: false,
                },
                ClientFrame::Request {
                    request_id: 1,
                    diagnostic_correlation: None,
                    request: Request::SubscribeConsentOffers {
                        kind: splinterm_protocol::ConsentResponderKind::Terminal,
                    },
                },
            ] {
                client
                    .write_all(&splinterm_protocol::encode_frame(&frame).unwrap())
                    .await
                    .unwrap();
            }
            assert!(matches!(
                controls.recv().await,
                Some(ControlFrame::Frame(ServerFrame::Hello { .. }))
            ));
            assert!(matches!(
                responses.recv().await.unwrap().frame,
                ServerFrame::Response {
                    request_id: 1,
                    result: Response::ConsentOffersSubscribed { .. },
                }
            ));
            assert_eq!(state.consent_responders.responder_count(), 1);
            // Prompts come and go while nothing reads the connection.
            let offered = consent::offered_lair_prompt(
                &with_start_time(PeerIdentity::for_test()),
                LairId::new(),
                "agents".into(),
                vec![AccessScope::Observe],
                consent::PromptDetails::once_only(),
            );
            let context = remote_consent::TreeContext {
                splint_leaders: Vec::new(),
                workload_slices: None,
                requester: Some(remote_consent::Requester {
                    pid: 300,
                    start_time: 40,
                }),
            };
            for request_id in 1..=32 {
                if state.consent_responders.responder_count() == 0 {
                    break;
                }
                drop(
                    state
                        .consent_responders
                        .open_round(
                            request_id,
                            offered.clone(),
                            Instant::now() + Duration::from_secs(60),
                            context.clone(),
                            Arc::default(),
                        )
                        .await,
                );
                time::sleep(Duration::from_millis(5)).await;
            }
            assert_eq!(state.consent_responders.responder_count(), 0);
            // Whatever else the trusted UI is sent comes first.
            loop {
                if let ControlFrame::Frame(ServerFrame::Error {
                    request_id: None,
                    error,
                }) = controls.recv().await.expect("the connection says why")
                {
                    assert_eq!(error.code, ErrorCode::ResourceLimit);
                    assert_eq!(error.message, remote_consent::RESPONDER_LAGGED);
                    break;
                }
            }
            // And then closes.
            let _ = task.await.unwrap();
        })
        .await
        .expect("the lagging responder's connection closes");
    }

    #[tokio::test]
    async fn a_duration_the_prompt_does_not_offer_leaves_the_offer_open() {
        let state = headless(test_state(false));
        let lair_id = insert_test_lair(&state, "agents").await;
        // Without a pinned identity only "Just this once" is offered.
        let peer = with_start_time(PeerIdentity::for_test());
        let mut responder = TestResponder::subscribe(&state, 11).await;
        let waiting = spawn_ask(
            &state,
            &peer,
            lair_request(lair_id, &[AccessScope::Observe], 5_000),
        );
        let offer = responder.offer().await;
        let always = ConsentDecision::Grant {
            duration: splinterm_protocol::GrantDuration::Remembered,
        };
        assert_eq!(
            responder
                .answer(&state, &offer, always)
                .await
                .unwrap_err()
                .code,
            ErrorCode::InvalidArgument
        );
        assert!(responder.quiet(), "the offer is still outstanding");
        assert_eq!(
            responder.answer(&state, &offer, ONCE).await,
            Ok(Response::ConsentOfferAnswered)
        );
        granted(finished(waiting).await.unwrap());
    }

    #[tokio::test]
    async fn every_unanswered_end_withdraws_the_offer_with_its_reason() {
        use splinterm_protocol::ConsentOfferEnd;

        let state = headless(test_state(false));
        let peer = with_start_time(PeerIdentity::for_test());
        let process = pending_access::ProcessKey::of(&peer).unwrap();
        let mut responder = TestResponder::subscribe(&state, 11).await;
        let scopes = [AccessScope::Observe];
        for (name, reason) in [
            ("cancel", ConsentOfferEnd::Cancelled),
            ("expiry", ConsentOfferEnd::Expired),
            ("workspace end", ConsentOfferEnd::RequestEnded),
            ("revoke all", ConsentOfferEnd::Cancelled),
            ("fence", ConsentOfferEnd::Fenced),
        ] {
            let lair_id = insert_test_lair(&state, name).await;
            let request_id = pending_request_id(
                &ask(&state, &peer, lair_request(lair_id, &scopes, 0))
                    .await
                    .unwrap(),
            );
            let offer = responder.offer().await;
            assert_eq!(offer.request_id, request_id);
            let mut fence = None;
            match name {
                "cancel" => assert!(state.pending_access.cancel(&process, lair_id, request_id)),
                "expiry" => assert!(
                    state
                        .pending_access
                        .expire(request_id, Instant::now() + Duration::from_secs(600))
                ),
                "workspace end" => end_lair_grants(&state, lair_id, "test workspace end").await,
                "revoke all" => assert_eq!(state.pending_access.cancel_all(), 1),
                _ => {
                    let mut attempt = HandoffAttempt::begin(&state).await.unwrap();
                    attempt.fence().await.unwrap();
                    fence = Some(attempt);
                }
            }
            assert_eq!(
                responder.withdrawn().await,
                (offer.offer_id, reason),
                "{name}"
            );
            wait_until_no_request_is_pending(&state).await;
            if let Some(attempt) = fence {
                // The fence refuses every answer while it holds.
                assert_eq!(
                    responder
                        .answer(&state, &offer, ONCE)
                        .await
                        .unwrap_err()
                        .code,
                    ErrorCode::HandoffInProgress
                );
                attempt.cancel(HandoffCancelReason::Requested).await;
            }
            // The withdrawn offer answers nothing and grants nothing.
            assert_eq!(
                responder
                    .answer(&state, &offer, ONCE)
                    .await
                    .unwrap_err()
                    .code,
                ErrorCode::NotFound,
                "{name}"
            );
            time::sleep(Duration::from_millis(20)).await;
            assert!(!has_once_grant(&state, &peer, lair_id).await, "{name}");
        }
        assert!(responder.quiet());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_restore_refused_by_a_starting_handoff_keeps_the_exited_runtime() {
        let state = test_state_with_backend(false, test_pty_backend());
        let expected = state.topology.read().await.revision();
        let Response::LairCreated { lair, .. } = trusted_request(
            &state,
            501,
            Request::CreateLair {
                expected_topology_revision: expected,
                name: "exits".into(),
                launch: test_launch(&["/bin/sh", "-c", "true"]),
                generated_name: false,
            },
        )
        .await
        .unwrap() else {
            panic!("create response was not returned");
        };
        let splint_id = lair.dojos[0].default_focus;
        time::timeout(Duration::from_secs(5), async {
            while !state
                .topology
                .read()
                .await
                .find_splint(splint_id)
                .is_some_and(|splint| matches!(splint.state, SplintState::Exited(_)))
            {
                time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("the process exits");
        let exited = state
            .runtimes
            .lock()
            .await
            .handle(splint_id)
            .expect("the exited runtime stays registered")
            .incarnation
            .value();

        let attempt = HandoffAttempt::begin(&state).await.unwrap();
        let launch = test_launch(&["/bin/sh", "-c", "true"]);
        let refused = start_exited_splint(&state, splint_id, &launch)
            .await
            .unwrap_err();
        assert_eq!(refused.code, ErrorCode::HandoffInProgress);
        assert_eq!(
            state
                .runtimes
                .lock()
                .await
                .handle(splint_id)
                .map(|handle| handle.incarnation.value()),
            Some(exited),
            "a refused restore leaves the exited runtime in place"
        );
        attempt.cancel(HandoffCancelReason::Requested).await;

        let (restored, _) = start_exited_splint(&state, splint_id, &launch)
            .await
            .unwrap();
        assert_ne!(restored, exited);
    }

    #[test]
    fn interactive_bypass_skips_redundant_policy_and_handler_authorization() {
        let untrusted = RequestAuthorizationContext::default();
        assert!(untrusted.requires_terminate_scope_authorization());
        assert!(!untrusted.may_manage_authorization(false, false));
        let interactive = RequestAuthorizationContext {
            interactive_bypass: true,
            ..RequestAuthorizationContext::default()
        };
        assert!(!interactive.requires_terminate_scope_authorization());
        assert!(interactive.may_manage_authorization(false, false));
    }

